const Q32=[
{n:1,q:"La Ley de Bases sobre Tráfico, Circulación de Vehículos a Motor y Seguridad Vial, fue aprobada por el/la:",o:{a:"Ley 18/1989.",b:"Real Decreto Legislativo 339/1990.",c:"Real Decreto Legislativo 18/1989.",d:"Ley 339/1990."},correct:"a",why:{a:"Correcto: la Ley 18/1989 es la Ley de Bases.",b:"El RDL 339/1990 es el Texto Articulado, no la Ley de Bases.",c:"No existe ese RDL.",d:"No existe esa Ley."}},
{n:2,q:"El Texto Articulado de la Ley sobre Tráfico, Circulación de Vehículos a Motor y Seguridad Vial, fue aprobado por el/la:",o:{a:"Real Decreto 339/1990, de 2 de febrero.",b:"Real Decreto Legislativo 339/1990, de 2 de marzo.",c:"Ley 18/1989, de 2 de marzo.",d:"Ley de Bases 18/1989, de 25 de julio."},correct:"b",why:{a:"La fecha es incorrecta (febrero en lugar de marzo).",b:"Correcto: RDL 339/1990 de 2 de marzo.",c:"La Ley 18/1989 es la Ley de Bases, no el Texto Articulado.",d:"La Ley 18/1989 es la Ley de Bases."}},
{n:3,q:"El Texto Refundido de la Ley sobre Tráfico, Circulación de Vehículos a Motor y Seguridad Vial, fue aprobado por el/la:",o:{a:"El Real Decreto 5/2015 de 30 de noviembre.",b:"El Real Decreto Legislativo 5/2015, de 30 de octubre.",c:"El Real Decreto Legislativo 6/2015, de 30 de noviembre.",d:"El Real Decreto Legislativo 6/2015, de 30 de octubre."},correct:"d",why:{a:"No es un Real Decreto sino un Real Decreto Legislativo.",b:"El número es 6, no 5.",c:"La fecha es 30 de octubre, no noviembre.",d:"Correcto: RDL 6/2015 de 30 de octubre."}},
{n:4,q:"La Ley de Seguridad Vial (RDL 6/2015) consta de:",o:{a:"Un título preliminar y seis títulos más.",b:"Seis títulos.",c:"Cinco títulos, incluido el preliminar.",d:"Siete títulos."},correct:"a",why:{a:"Correcto: título preliminar + seis títulos (I al VI).",b:"Son seis títulos más el preliminar.",c:"Son seis títulos más el preliminar.",d:"No."}},
{n:5,q:"La Ley de Seguridad Vial (RDL 6/2015), tiene...",o:{a:"Nueve anexos.",b:"Ocho anexos.",c:"Siete anexos.",d:"Seis anexos."},correct:"a",why:{a:"Correcto: nueve anexos.",b:"No.",c:"No.",d:"No."}},
{n:6,q:"La Ley de Seguridad Vial (RDL 6/2015):",o:{a:"Tiene rango de ley orgánica.",b:"Consta de siete títulos más el preliminar.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"d",why:{a:"No tiene rango de ley orgánica.",b:"Tiene seis títulos más el preliminar, no siete.",c:"Ambas son incorrectas.",d:"Correcto: las dos afirmaciones son falsas."}},
{n:7,q:"El Título Preliminar de la Ley de Seguridad Vial (RDL 6/2015), se denomina \"Disposiciones generales\" y comprende:",o:{a:"Los artículos 1, 2 y 3.",b:"Los artículos 1 a 9.",c:"Los artículos 1 a 10.",d:"Los artículos 1 a 7."},correct:"a",why:{a:"Correcto: arts. 1, 2 y 3.",b:"No.",c:"No.",d:"No."}},
{n:8,q:"En el Título Preliminar de la Ley de Seguridad Vial (RDL 6/2015), se contiene:",o:{a:"El objeto y ámbito de aplicación de esta Ley, así como una remisión a su Anexo I sobre los conceptos básicos.",b:"Una declaración de intenciones sobre la finalidad de esta Ley.",c:"Una remisión a su Anexo II sobre el cuadro de infracciones y sanciones.",d:"Todas las respuestas anteriores son correctas."},correct:"a",why:{a:"Correcto: objeto, ámbito y remisión al Anexo I.",b:"No.",c:"El Anexo II no es el cuadro de infracciones.",d:"Solo la a es correcta."}},
{n:9,q:"El Título Preliminar de la Ley de Seguridad Vial (RDL 6/2015), establece que, a los efectos de esta ley y sus disposiciones complementarias, los conceptos básicos sobre vehículos, vías públicas y usuarios de las mismas son:",o:{a:"Los previstos en su anexo I.",b:"Los previstos en su anexo II.",c:"Los previstos en su anexo III.",d:"Los previstos en su anexo IV."},correct:"a",why:{a:"Correcto: Anexo I contiene los conceptos básicos.",b:"No.",c:"No.",d:"No."}},
{n:10,q:"La Ley de Seguridad Vial (RDL 6/2015) tiene por objeto regular el tráfico, la circulación de todos los vehículos y la seguridad vial y, a tal efecto, regula (indique la afirmación incorrecta):",o:{a:"El ejercicio de las competencias que, de acuerdo con la Constitución Española y los estatutos de autonomía, corresponden en tales materias a la Administración General del Estado y a las CCAA que hayan recibido el traspaso de funciones y servicios en esta materia, así como la determinación de las que corresponden en todo caso a las entidades locales.",b:"Las autorizaciones que, para garantizar la seguridad y fluidez de la circulación, otorga la Administración con carácter previo a la realización de actividades relacionadas con la circulación de vehículos, especialmente a motor, así como las medidas cautelares que adopte con el mismo fin.",c:"Las normas de circulación para los vehículos, así como las que por razón de seguridad vial rigen para la circulación de peatones y animales por las vías de utilización general, estableciéndose a tal efecto los derechos y obligaciones de los usuarios de dichas vías.",d:"Los elementos de seguridad activa y su régimen de utilización, así como las condiciones técnicas de los vehículos y de las actividades industriales que afectan de manera directa o indirecta a la seguridad vial."},correct:"d",why:{a:"Correcto, sí lo regula.",b:"Correcto, sí lo regula.",c:"Correcto, sí lo regula.",d:"Incorrecto: los elementos de seguridad activa no se regulan en este objeto según la LSV."}},
{n:11,q:"La Ley de Seguridad Vial (RDL 6/2015) tiene por objeto regular el tráfico, la circulación de todos los vehículos y la seguridad vial y, a tal efecto, regula (indique la afirmación incorrecta):",o:{a:"Los criterios de señalización de las vías de utilización general.",b:"Las autorizaciones que, en su caso, para garantizar la seguridad y fluidez de la circulación, podrá otorgar la Administración para la realización de actividades relacionadas con la circulación de vehículos, especialmente a motor.",c:"Las infracciones derivadas del incumplimiento de las normas establecidas y las sanciones aplicables a las mismas, así como el procedimiento sancionador en esta materia.",d:"Los elementos de seguridad activa y su régimen de utilización, así como las condiciones técnicas de los vehículos y de las actividades industriales que afectan de manera directa o indirecta a la seguridad vial."},correct:"b",why:{a:"Sí lo regula.",b:"Incorrecto como redactado: la administración otorga autorizaciones, no podrá otorgarlas discrecionalmente en la forma descrita.",c:"Sí lo regula.",d:"Sí lo regula."}},
{n:12,q:"De conformidad con lo establecido en el art.2 de la Ley de Seguridad Vial (RDL 6/2015), los preceptos de esta ley son aplicables en todo el territorio nacional y obligan:",o:{a:"A los titulares y usuarios de las vías y terrenos públicos aptos para la circulación, tanto urbanos como interurbanos.",b:"A los titulares de las vías y terrenos que, sin tener la aptitud de públicos, sean de uso común.",c:"En defecto de otras normas, a los titulares de las vías y terrenos privados que sean utilizados por una colectividad indeterminada de usuarios.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{a:"Cierto.",b:"Cierto.",c:"Cierto.",d:"Correcto: las tres."}},
{n:13,q:"El Título I de la Ley de Seguridad Vial (RDL 6/2015) lleva por título:",o:{a:"\"Ejercicio y coordinación de las competencias sobre tráfico, circulación de vehículos a motor y seguridad vial\".",b:"\"Objetivo de la Ley y su ámbito de aplicación\".",c:"\"Las competencias\".",d:"\"El Consejo Superior de Tráfico, Seguridad Vial y Movilidad Sostenible\"."},correct:"a",why:{a:"Correcto.",b:"No.",c:"No.",d:"No."}},
{n:14,q:"El Título I de la Ley de Seguridad Vial (RDL 6/2015) se divide en tres capítulos. Indique cual de los siguientes no es uno de ellos:",o:{a:"\"Competencias\".",b:"\"Organismo Autónomo Jefatura Central de Tráfico\".",c:"\"Consejo Superior de Tráfico, Seguridad Vial y Movilidad Sostenible\".",d:"\"Conferencia Sectorial de Tráfico, Seguridad Vial y Movilidad Sostenible\"."},correct:"b",why:{a:"Sí es capítulo del Título I.",b:"Correcto: no es un capítulo del Título I.",c:"Sí es capítulo del Título I.",d:"Sí es capítulo del Título I."}},
{n:15,q:"En la Ley de Seguridad Vial (RDL 6/2015), las competencias de los municipios...",o:{a:"Están reguladas en el capítulo I del Título I.",b:"Están reguladas en su artículo 7.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{a:"Cierto.",b:"Cierto.",c:"Correcto: Cap.I Título I y art.7.",d:"Las dos son ciertas."}},
{n:16,q:"En la Ley de Seguridad Vial (RDL 6/2015), la Conferencia Sectorial de Tráfico, Seguridad Vial y Movilidad Sostenible...",o:{a:"Está regulada en el capítulo II del Título I.",b:"Está regulada en su artículo 9.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"b",why:{a:"No está en el Cap.II del Título I.",b:"Correcto: está en el art.9.",c:"La a es incorrecta.",d:"La b sí es correcta."}},
{n:17,q:"El Título II de la Ley de Seguridad Vial (RDL 6/2015) está dedicado:",o:{a:"Al Consejo Superior de Tráfico, Seguridad Vial y Movilidad Sostenible.",b:"A las normas de comportamiento en la circulación.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"b",why:{a:"El Consejo Superior está en el Título I.",b:"Correcto: Título II = normas de comportamiento.",c:"La a es incorrecta.",d:"La b sí es correcta."}},
{n:18,q:"El Título II de la Ley de Seguridad Vial (RDL 6/2015) se divide en tres capítulos. Indique cual de los siguientes no es uno de ellos:",o:{a:"\"Competencias\".",b:"\"Normas generales\".",c:"\"Circulación de vehículos\".",d:"\"Otras normas de circulación\"."},correct:"a",why:{a:"Correcto: «Competencias» pertenece al Título I, no al II.",b:"Sí es capítulo del Título II.",c:"Sí es capítulo del Título II.",d:"Sí es capítulo del Título II."}},
{n:19,q:"El Título III de la Ley de Seguridad Vial (RDL 6/2015) está dedicado:",o:{a:"A las normas de comportamiento en la circulación.",b:"A la señalización.",c:"Al Régimen Sancionador.",d:"A la Circulación de Vehículos."},correct:"b",why:{a:"Eso es el Título II.",b:"Correcto: Título III = señalización.",c:"Eso es el Título V.",d:"No."}},
{n:20,q:"El Título III de la Ley de Seguridad Vial (RDL 6/2015) consta de:",o:{a:"6 artículos.",b:"5 capítulos.",c:"4 capítulos.",d:"3 capítulos y 17 artículos."},correct:"a",why:{a:"Correcto: 6 artículos (arts. 56-61).",b:"No.",c:"No.",d:"No."}},
{n:21,q:"El Título IV de la Ley de Seguridad Vial (RDL 6/2015) consta de cuatro capítulos y está dedicado:",o:{a:"A las normas de comportamiento en la circulación.",b:"A la ejecución de las sanciones.",c:"A otras normas de circulación.",d:"A las autorizaciones administrativas."},correct:"d",why:{a:"Eso es el Título II.",b:"No.",c:"No.",d:"Correcto: Título IV = autorizaciones administrativas."}},
{n:22,q:"Las autorizaciones relativas a los vehículos se regulan en el Título IV de la Ley de Seguridad Vial (RDL 6/2015), y más concretamente en:",o:{a:"Su Capítulo I.",b:"Su Capítulo II.",c:"Su Capítulo III.",d:"Su Capítulo IV."},correct:"c",why:{a:"Cap.I = Disposiciones generales.",b:"Cap.II = Permiso de conducción.",c:"Correcto: Cap.III = Permiso de circulación de vehículos.",d:"Cap.IV = Pérdida de vigencia."}},
{n:23,q:"El Título V de la Ley de Seguridad Vial (RDL 6/2015) se estructura en ocho capítulos y está dedicado:",o:{a:"A la señalización.",b:"Al régimen sancionador.",c:"Al Registro Nacional de Víctimas de Accidentes de Tráfico.",d:"A las autorizaciones administrativas."},correct:"b",why:{a:"Eso es el Título III.",b:"Correcto: Título V = régimen sancionador (8 capítulos).",c:"No.",d:"Eso es el Título IV."}},
{n:24,q:"El Título VI de la Ley de Seguridad Vial (RDL 6/2015) está dedicado:",o:{a:"A la señalización.",b:"Al procedimiento sancionador.",c:"A las autorizaciones administrativas.",d:"Ninguna de las respuestas anteriores es correcta."},correct:"d",why:{a:"No.",b:"El procedimiento sancionador está en el Título V.",c:"Eso es el Título IV.",d:"Correcto: el Título VI está dedicado al Registro de Conductores e Infractores."}},
{n:25,q:"La Ley de Seguridad Vial (RDL 6/2015) tiene estructurado en ocho capítulos:",o:{a:"Su Título II.",b:"Su Título III.",c:"Su Título V.",d:"Su Título VI."},correct:"c",why:{a:"El Título II tiene tres capítulos.",b:"El Título III tiene artículos, no capítulos numerados.",c:"Correcto: Título V (régimen sancionador) tiene 8 capítulos.",d:"No."}},
{n:26,q:"La regulación del Consejo Superior de Tráfico, Seguridad Vial y Movilidad Sostenible se contiene en la Ley de Seguridad Vial (RDL 6/2015):",o:{a:"En su Capítulo I del Título I.",b:"En su Capítulo I del Título II.",c:"Dentro de su Capítulo II del Título I.",d:"Dentro de su Capítulo II del Título II."},correct:"c",why:{a:"Cap.I Título I = Competencias.",b:"No.",c:"Correcto: Cap.II del Título I.",d:"No."}},
{n:27,q:"La regulación de las autorizaciones para conducir se contiene en la Ley de Seguridad Vial (RDL 6/2015), dentro de su:",o:{a:"Capítulo I del Título III.",b:"Capítulo III del Título IV.",c:"Capítulo II del Título IV.",d:"Capítulo IV del Título V."},correct:"c",why:{a:"No.",b:"Cap.III del T.IV = permiso de circulación.",c:"Correcto: Cap.II del Título IV = permiso de conducción.",d:"No."}},
{n:28,q:"La medida provisional de retirada y depósito del vehículo se encuentra regulada en la Ley de Seguridad Vial (RDL 6/2015), y más concretamente en el:",o:{a:"Capítulo V del Título V.",b:"Capítulo IV del Título V.",c:"Capítulo V del Título IV.",d:"Capítulo II del Título II."},correct:"d",why:{a:"No.",b:"No.",c:"El Título IV solo tiene 4 capítulos.",d:"Correcto."}},
{n:29,q:"El Registro Estatal de Víctimas y Accidentes de Tráfico está regulado en la Ley de Seguridad Vial (RDL 6/2015), y más concretamente en el:",o:{a:"Capítulo IV del Título V.",b:"Capítulo VI del Título V.",c:"Capítulo IV del Título VI.",d:"Título VI."},correct:"d",why:{a:"No.",b:"No.",c:"No.",d:"Correcto: el Registro de Víctimas está en el Título VI."}},
{n:30,q:"El intercambio transfronterizo de información sobre infracciones de tráfico está regulado en la Ley de Seguridad Vial (RDL 6/2015), y más concretamente en el:",o:{a:"Capítulo V del Título V.",b:"Capítulo IV del Título V.",c:"Capítulo VI del Título VI.",d:"Capítulo V del Título VI."},correct:"a",why:{a:"Correcto: Cap.V del Título V.",b:"No.",c:"No.",d:"No."}},
{n:31,q:"El Anexo I de la Ley de Seguridad Vial (RDL 6/2015) se denomina:",o:{a:"Conceptos básicos.",b:"Infracciones que llevan aparejada la pérdida de puntos.",c:"Cursos de sensibilización y reeducación vial.",d:"Ninguna de las respuestas anteriores es correcta."},correct:"a",why:{a:"Correcto: Anexo I = Conceptos básicos.",b:"No.",c:"No.",d:"La a es correcta."}},
{n:32,q:"El Anexo II de la Ley de Seguridad Vial (RDL 6/2015) se denomina:",o:{a:"Datos que se facilitarán por los órganos competentes españoles.",b:"Infracciones que llevan aparejada la pérdida de puntos.",c:"Cursos de sensibilización y reeducación vial.",d:"Cuadro de sanciones y puntos por exceso de velocidad."},correct:"b",why:{a:"No.",b:"Correcto: Anexo II = Infracciones con pérdida de puntos.",c:"No.",d:"No."}},
{n:33,q:"El Anexo III de la Ley de Seguridad Vial (RDL 6/2015) está dedicado a:",o:{a:"Los conceptos básicos.",b:"Las infracciones que llevan aparejada la pérdida de puntos.",c:"Los cursos de sensibilización y reeducación vial.",d:"La carta de información."},correct:"c",why:{a:"Eso es el Anexo I.",b:"Eso es el Anexo II.",c:"Correcto: Anexo III = Cursos de sensibilización y reeducación.",d:"No."}},
{n:34,q:"El Anexo IV de la Ley de Seguridad Vial (RDL 6/2015) se denomina:",o:{a:"Datos de búsqueda a los que podrán acceder los órganos competentes españoles.",b:"Infracciones que llevan aparejada la pérdida de puntos.",c:"Cuadro de sanciones y puntos por exceso de velocidad.",d:"Datos que se facilitarán por los órganos competentes españoles."},correct:"a",why:{a:"Correcto: Anexo IV = Datos de búsqueda para los órganos competentes españoles.",b:"No.",c:"No.",d:"No."}},
{n:35,q:"El Anexo V de la Ley de Seguridad Vial (RDL 6/2015) se refiere:",o:{a:"A los datos de búsqueda a los que podrán acceder los órganos competentes españoles dentro del intercambio transfronterizo de información.",b:"A los conceptos básicos.",c:"A las notificaciones.",d:"A las infracciones que llevan aparejada la pérdida de puntos."},correct:"a",why:{a:"Correcto: Anexo V = datos de búsqueda accesibles a órganos españoles.",b:"Eso es el Anexo I.",c:"No.",d:"Eso es el Anexo II."}},
{n:36,q:"El Anexo VI de la Ley de Seguridad Vial (RDL 6/2015) se denomina:",o:{a:"Infracciones que llevan aparejada la pérdida de puntos.",b:"Datos que se facilitarán por los órganos competentes españoles.",c:"Cursos de sensibilización y reeducación vial.",d:"Cuadro de sanciones y puntos por exceso de velocidad."},correct:"b",why:{a:"No.",b:"Correcto: Anexo VI = Datos que facilitarán los órganos competentes españoles.",c:"No.",d:"No."}},
{n:37,q:"En la Ley de Seguridad Vial (RDL 6/2015), el modelo de la carta de información se contiene en el:",o:{a:"Anexo V, denominado \"datos a facilitar por órganos competentes españoles\".",b:"Anexo IV, denominado \"cuadro de sanciones y puntos por exceso de velocidad\".",c:"Anexo VI, denominado \"conceptos básicos\".",d:"Anexo VII, denominado \"notificaciones\"."},correct:"d",why:{a:"No.",b:"No.",c:"No.",d:"Correcto: Anexo VII = notificaciones (modelo de carta de información)."}},
{n:38,q:"En la Ley de Seguridad Vial (RDL 6/2015), el enunciado \"Nulidad, lesividad y pérdida de vigencia de la autorización. Obtención de un nuevo permiso o licencia de conducción\" es la denominación que recibe...",o:{a:"El Anexo VI.",b:"El Capítulo IV del Título V.",c:"El Capítulo V del Título V.",d:"El Capítulo II del Título IV."},correct:"b",why:{a:"No.",b:"Correcto: Cap.IV del Título V.",c:"No.",d:"No."}},
{n:39,q:"En la Ley de Seguridad Vial (RDL 6/2015), el enunciado \"Prescripción, caducidad y cancelación de antecedentes\" es la denominación que recibe...",o:{a:"El Capítulo VI del Título V.",b:"El Capítulo IV del Título V.",c:"El Capítulo VI del Título VI.",d:"El Capítulo V del Título V."},correct:"d",why:{a:"No.",b:"No.",c:"No.",d:"Correcto: Cap.V del Título V."}},
{n:40,q:"El Anexo VIII de la Ley de Seguridad Vial (RDL 6/2015) se denomina:",o:{a:"Centros de sensibilización y reeducación vial.",b:"Datos de búsqueda a los que podrán acceder los órganos competentes españoles.",c:"Datos que se facilitarán por los órganos competentes españoles.",d:"Datos que se facilitarán por los órganos competentes españoles."},correct:"b",why:{a:"No.",b:"Correcto: Anexo VIII.",c:"Igual que b, solo uno puede ser correcto.",d:"No."}},
{n:41,q:"El Anexo IX de la Ley de Seguridad Vial (RDL 6/2015) se denomina:",o:{a:"Centros de sensibilización y reeducación vial.",b:"Datos de búsqueda a los que podrán acceder los órganos competentes españoles.",c:"Datos que se facilitarán por los órganos competentes españoles.",d:"Cuadro de sanciones y puntos por exceso de velocidad."},correct:"a",why:{a:"Correcto: Anexo IX = Centros de sensibilización y reeducación vial.",b:"No.",c:"No.",d:"No."}},
{n:42,q:"El Anexo I de la Ley de Seguridad Vial (RDL 6/2015) se denomina «conceptos básicos» y entre las definiciones que contiene no se encuentra la de:",o:{a:"Conductor.",b:"Conductor eventual.",c:"Conductor profesional.",d:"Conductor habitual."},correct:"b",why:{a:"Sí está definido.",b:"Correcto: «conductor eventual» no aparece entre las definiciones del Anexo I.",c:"Sí está definido.",d:"Sí está definido."}},
{n:43,q:"De las definiciones contenidas en el Anexo I de la Ley de Seguridad Vial (RDL 6/2015), indique cual de las siguientes es incorrecta:",o:{a:"Conductor: Persona que, con las excepciones del párrafo segundo de la definición de peatones de este anexo, maneja el mecanismo de dirección o va al mando de un vehículo, o a cuyo cargo está un animal o animales.",b:"Conductor eventual: Persona que, contando con el permiso o licencia de conducción necesarios, inscrito en el Registro de Conductores e Infractores y previo su consentimiento, se comunica por el titular del vehículo o, en su caso, por el arrendatario a largo plazo al Registro de Vehículos, por ser aquella que de manera eventual conduce dicho vehículo.",c:"Conductor habitual: Persona que, contando con el permiso o licencia de conducción necesarios, inscrito en el Registro de Conductores e Infractores y previo su consentimiento, se comunica por el titular del vehículo o, en su caso, por el arrendatario a largo plazo al Registro de Vehículos, por ser aquella que de manera usual o con mayor frecuencia conduce dicho vehículo.",d:"Conductor profesional: Persona provista de la correspondiente autorización administrativa para conducir, cuya actividad laboral principal sea la conducción de vehículos a motor dedicados al transporte de mercancías o de personas."},correct:"a",why:{a:"Incorrecto: la definición de conductor omite que puede ir «a pie empujando» el vehículo; la redacción no es la del Anexo I.",b:"Cierto.",c:"Cierto.",d:"Cierto."}},
{n:44,q:"Según las definiciones contenidas en el Anexo I de la Ley de Seguridad Vial (RDL 6/2015):",o:{a:"En vehículos que circulen en función de aprendizaje de la conducción, tiene la consideración de conductor la persona que está a cargo de los mandos adicionales.",b:"La certificación específica que se requiere a un conductor profesional, cuando se trate de un empresario autónomo, será sustituida por una declaración del propio empresario.",c:"Titular de vehículo es la persona a cuyo nombre figura inscrito el vehículo en el registro oficial correspondiente.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{a:"Cierto.",b:"Cierto.",c:"Cierto.",d:"Correcto: las tres."}},
{n:45,q:"Según las definiciones contenidas en el Anexo I de la Ley de Seguridad Vial (RDL 6/2015):",o:{a:"Peatón es la persona que, sin ser conductor, transita a pie por las vías o terrenos a que se refiere el artículo 2 de este RDL.",b:"Tienen la consideración de peatones quienes empujan o arrastran un coche de niño o de una persona con discapacidad y quienes conducen cualquier otro vehículo sin motor de pequeñas dimensiones.",c:"Tienen la consideración de peatones las personas con discapacidad que circulan al paso en una silla de ruedas y las personas con discapacidad que circulan en una silla de ruedas, con o sin motor.",d:"Todas las respuestas anteriores son correctas."},correct:"a",why:{a:"Correcto: definición de peatón.",b:"No incluye a los que conducen vehículos sin motor.",c:"Las que van en silla de ruedas con motor no son peatones.",d:"Solo la a."}},
{n:46,q:"Según las definiciones contenidas en el Anexo I de la Ley de Seguridad Vial (RDL 6/2015):",o:{a:"Vehículo es el aparato apto para circular por las vías o terrenos a que se refiere el artículo 2 de este RDL.",b:"Ciclo es el vehículo provisto de ruedas y propulsado exclusivamente por la energía muscular de la persona o personas que están sobre el vehículo, principalmente por medio de pedales, incluyéndose en esta definición los ciclos de pedaleo asistido.",c:"Bicicleta es el Ciclo provisto de, al menos, dos ruedas.",d:"Todas las respuestas anteriores son correctas."},correct:"a",why:{a:"Correcto: definición de vehículo.",b:"El ciclo de pedaleo asistido no se incluye en la definición de ciclo.",c:"La bicicleta es un tipo de ciclo.",d:"Las b y c tienen matices incorrectos."}},
{n:47,q:"Según las definiciones contenidas en el Anexo I de la Ley de Seguridad Vial (RDL 6/2015):",o:{a:"Ciclo es el vehículo provisto de, al menos, dos ruedas y propulsado exclusiva o principalmente por la energía muscular de la persona o personas que están sobre el vehículo, en particular por medio de pedales. Se incluyen en esta definición los ciclos de dos ruedas.",b:"Bicicleta es el ciclo de dos ruedas.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{a:"Cierto.",b:"Cierto.",c:"Correcto: ambas.",d:"Las dos son ciertas."}},
{n:48,q:"Según las definiciones contenidas en el Anexo I de la Ley de Seguridad Vial (RDL 6/2015), tienen la condición de ciclomotores:",o:{a:"Los vehículos de dos ruedas, con una velocidad máxima por construcción no superior a 45 km/h y con un motor de cilindrada inferior o igual a 50 cm³, si es de combustión interna, o bien con una potencia continua nominal máxima inferior o igual a 4 kW si es de motor eléctrico.",b:"Los vehículos de tres ruedas, con una velocidad máxima por construcción no superior a 45 km/h y con un motor cuya cilindrada sea inferior o igual a 50 cm³ para los motores de encendido por chispa (positiva), o bien cuya potencia máxima neta sea inferior o igual a 4 kW para los demás motores de combustión interna, o bien cuya potencia continua nominal máxima sea inferior o igual a 4 kW para los motores eléctricos.",c:"Los vehículos de cuatro ruedas, cuya masa en vacío sea inferior o igual a 350 kilogramos no incluida la masa de baterías para los vehículos eléctricos, cuya velocidad máxima por construcción sea inferior o igual a 45 km/h y cuya cilindrada del motor sea inferior o igual a 50 cm³ para los motores de encendido por chispa (positiva), o cuya potencia máxima neta sea inferior o igual a 4 kW para los demás motores de combustión interna, o cuya potencia continua nominal máxima sea inferior o igual a 4 kW para los motores eléctricos.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{a:"Cierto.",b:"Cierto.",c:"Cierto.",d:"Correcto: las tres categorías de ciclomotores."}},
{n:49,q:"Según las definiciones contenidas en el Anexo I de la Ley de Seguridad Vial (RDL 6/2015):",o:{a:"Tranvía es el vehículo que marcha por raíles instalados en la vía.",b:"Vehículo para personas de movilidad reducida es el vehículo cuya tara no sea superior a 250 kilogramos y que, por construcción, no puede alcanzar en llano una velocidad superior a 55 km/h.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{a:"Cierto.",b:"Cierto (tara ≤250 kg y velocidad máx. 55 km/h según el Anexo I).",c:"Correcto: ambas.",d:"Las dos son ciertas."}},
{n:50,q:"Según las definiciones contenidas en el Anexo I de la Ley de Seguridad Vial (RDL 6/2015), el vehículo para personas de movilidad reducida:",o:{a:"Es el vehículo cuya tara no sea superior a 350 kilogramos y que, por construcción, no puede alcanzar en llano una velocidad superior a 45 km/h.",b:"Es el vehículo proyectado y construido especialmente (y no meramente adaptado) para el uso de personas con alguna disfunción o incapacidad física.",c:"Es el vehículo cuyas características técnicas, salvo las específicas señaladas en su definición, se equiparan a las de los ciclomotores de tres ruedas.",d:"Todas las respuestas anteriores son correctas."},correct:"a",why:{a:"Correcto: tara ≤350 kg y velocidad máx. en llano 45 km/h.",b:"No es necesario que sea especialmente construido, puede ser adaptado.",c:"Se equipara a ciclomotores, pero no solo de tres ruedas.",d:"Solo la a."}},
{n:51,q:"Según las definiciones contenidas en el Anexo I de la Ley de Seguridad Vial (RDL 6/2015), Vehículo de motor es el vehículo de motor para su propulsión, excluyéndose de esta definición:",o:{a:"Los ciclomotores, los tranvías y los vehículos para personas de movilidad reducida, los ciclos y las bicicletas.",b:"Los ciclos, los tranvías y las bicicletas.",c:"Los vehículos para personas de movilidad reducida, las motocicletas y los ciclomotores.",d:"Los tranvías, los vehículos para personas de movilidad reducida, los ciclos y las bicicletas."},correct:"a",why:{a:"Correcto: se excluyen ciclomotores, tranvías, vehículos PMR, ciclos y bicicletas.",b:"También se excluyen los ciclomotores y los PMR.",c:"No se excluyen las motocicletas.",d:"También se excluyen los ciclomotores."}},
{n:52,q:"Según las definiciones contenidas en el Anexo I de la Ley de Seguridad Vial (RDL 6/2015), automóvil es el vehículo de motor que sirve, normalmente:",o:{a:"Para el transporte de personas o de cosas, o de ambas a la vez.",b:"Para la tracción de otros vehículos con el fin de su transporte.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{a:"Cierto.",b:"Cierto.",c:"Correcto: ambas.",d:"Las dos son ciertas."}},
{n:53,q:"Según las definiciones contenidas en el Anexo I de la Ley de Seguridad Vial (RDL 6/2015), quedan excluidos de la definición de automóvil:",o:{a:"Los vehículos especiales.",b:"Los vehículos destinados al transporte de viajeros con capacidad superior a 60 pasajeros.",c:"Los vehículos destinados al transporte de mercancías cuya masa en vacío sea superior a 3.500 kilogramos.",d:"Están excluidos todos los citados en las respuestas anteriores."},correct:"a",why:{a:"Correcto: los vehículos especiales no son automóviles.",b:"Los autobuses de más de 60 plazas sí son automóviles (autobuses).",c:"Los camiones pesados sí son automóviles.",d:"Solo la a es correcta."}},
{n:54,q:"Según las definiciones contenidas en el Anexo I de la Ley de Seguridad Vial (RDL 6/2015), tiene la condición de motocicleta:",o:{a:"El automóvil de dos ruedas, sin sidecar, provisto de un motor de cilindrada superior a 50 cm³, si es de combustión interna, y/o con una velocidad máxima por construcción superior a 45 km/h. (Motocicleta de dos ruedas).",b:"El automóvil de tres ruedas asimétricas respecto a su eje medio longitudinal, provisto de un motor de cilindrada superior a 50 cm³, si es de combustión interna, y/o con una velocidad máxima por construcción superior a 45 km/h. (Motocicleta con sidecar).",c:"Las respuestas a y b son incorrectas.",d:"Las respuestas a y b son correctas."},correct:"d",why:{a:"Cierto.",b:"Cierto.",c:"Las dos son correctas.",d:"Correcto: ambas."}},
{n:55,q:"De las definiciones contenidas en el Anexo I de la Ley de Seguridad Vial (RDL 6/2015), indique cual de las siguientes es incorrecta:",o:{a:"Turismo: Automóvil destinado al transporte de personas que tenga, por lo menos, cuatro ruedas y que tenga, además del asiento del conductor, ocho plazas como máximo.",b:"Autobús o autocar: Automóvil que tenga más de nueve plazas, incluida la del conductor, destinado, por su construcción y acondicionamiento, al transporte de personas y sus equipajes. Se incluye en este término el trolebús, es decir, el vehículo conectado a una línea eléctrica y que no circula por raíles.",c:"Autobús o autocar articulado: Autobús o autocar compuesto por dos o más partes rígidas unidas entre sí por una sección articulada. En este tipo de vehículos, los compartimentos para viajeros de cada una de las partes rígidas podrán comunicarse entre sí, así como con la cabina.",d:"Camión: Automóvil con cuatro ruedas o más, concebido y construido para el transporte de mercancías, cuya cabina no está integrada en el resto de la carrocería y con un máximo de nueve plazas, incluido el conductor."},correct:"c",why:{a:"Cierto.",b:"Cierto.",c:"Incorrecto: el autobús articulado NO tiene la característica de comunicarse con la cabina; eso no está en la definición.",d:"Cierto."}},
{n:56,q:"Según las definiciones contenidas en el Anexo I de la Ley de Seguridad Vial (RDL 6/2015):",o:{a:"Autobús o autocar articulado es el que está compuesto por dos partes rígidas unidas entre sí por una sección articulada, y los compartimentos para viajeros de cada una de ambas partes rígidas se comunican entre sí.",b:"La sección articulada de un autobús o autocar articulado permite la libre circulación de los viajeros entre las dos partes rígidas.",c:"La conexión y disyunción entre las dos partes rígidas de un autobús o autocar articulado únicamente podrá realizarse en el taller.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{a:"Cierto.",b:"Cierto.",c:"Cierto.",d:"Correcto: las tres."}},
{n:57,q:"De las definiciones contenidas en el Anexo I de la Ley de Seguridad Vial (RDL 6/2015), indique cual de las siguientes es incorrecta:",o:{a:"Vehículo mixto adaptable: Automóvil especialmente dispuesto para el transporte, simultáneo o no, de mercancías y personas hasta un máximo de nueve incluido el conductor, y en el que se puede sustituir eventualmente la carga, parcial o totalmente, por personas mediante la adición de asientos.",b:"Semirremolque: Vehículo autopropulsado diseñado y concebido para ser acoplado a un automóvil, sobre el que reposará parte del mismo, transfiriéndole una parte sustancial de su masa.",c:"Remolque: Vehículo no autopropulsado diseñado y concebido para ser remolcado por un vehículo de motor.",d:"Remolque ligero: Aquél cuya masa máxima autorizada no exceda de 750 kg. A efectos de esta clasificación, se excluyen los agrícolas."},correct:"b",why:{a:"Cierto.",b:"Incorrecto: el semirremolque NO es autopropulsado; es un vehículo no autopropulsado.",c:"Cierto.",d:"Cierto."}},
{n:58,q:"Según las definiciones contenidas en el Anexo I de la Ley de Seguridad Vial (RDL 6/2015), el semirremolque es un vehículo:",o:{a:"No autopropulsado.",b:"Diseñado y concebido para ser acoplado a un automóvil, sobre el que reposará parte del mismo, transfiriéndole una parte sustancial de su masa.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{a:"Cierto.",b:"Cierto.",c:"Correcto: ambas.",d:"Las dos son ciertas."}},
{n:59,q:"Según las definiciones contenidas en el Anexo I de la Ley de Seguridad Vial (RDL 6/2015), el conjunto de vehículos:",o:{a:"El vehículo especial concebido y construido para el transporte, para trasladarse y maniobrar debe ser arrastrado o empujado por un tractor agrícola, motocultor, portador o máquina agrícola automotriz.",b:"El vehículo especial autopropulsado, de dos o más ejes, especialmente concebido para el transporte en campo de productos agrícolas.",c:"El vehículo especial autopropulsado, de dos o más ejes, concebido y construido para trabajos agrícolas.",d:"El vehículo especial autopropulsado, de dos o más ejes, especialmente concebido para portar máquinas agrícolas."},correct:"a",why:{a:"Correcto: descripción del conjunto de vehículos (tren de carretera).",b:"No.",c:"No.",d:"No."}},
{n:60,q:"Según las definiciones contenidas en el Anexo I de la Ley de Seguridad Vial (RDL 6/2015), el tren de carretera:",o:{a:"Es el automóvil constituido por un vehículo de motor enganchado a más de un remolque.",b:"Tiene la condición de vehículo mixto.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"d",why:{a:"No es esa la definición exacta.",b:"No es vehículo mixto.",c:"Ambas incorrectas.",d:"Correcto: las dos afirmaciones son incorrectas."}},
{n:61,q:"Según las definiciones contenidas en el Anexo I de la Ley de Seguridad Vial (RDL 6/2015), el tren de carretera:",o:{a:"Es el automóvil constituido por un vehículo de motor enganchado a más de un remolque.",b:"Tiene la condición de conjunto de vehículos.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{a:"Cierto.",b:"Cierto.",c:"Correcto: ambas.",d:"Las dos son ciertas."}},
{n:62,q:"De las definiciones contenidas en el Anexo I de la Ley de Seguridad Vial (RDL 6/2015), indique cual de las siguientes es incorrecta:",o:{a:"Tractocamión: Automóvil concebido y construido para realizar, principalmente, el arrastre de un semirremolque.",b:"Vehículo especial (VE): Vehículo, no autopropulsado o remolcado, concebido y construido para realizar obras o servicios determinados y que, por sus características, está exceptuado de cumplir alguna de las condiciones técnicas establecidas en el mismo para masas o dimensiones, así como la maquinaria agrícola y sus remolques.",c:"Tractor de obras: Vehículo especial autopropulsado, de dos o más ejes, concebido y construido para arrastrar o empujar útiles, máquinas o vehículos de obras.",d:"Tractor de servicios: Vehículo especial autopropulsado, de dos o más ejes, concebido y construido para arrastrar o empujar vehículos de servicio, vagones u otros aparatos."},correct:"b",why:{a:"Cierto.",b:"Incorrecto: el VE sí puede ser autopropulsado o remolcado; no es siempre no autopropulsado.",c:"Cierto.",d:"Cierto."}},
{n:63,q:"Según las definiciones contenidas en el Anexo I de la Ley de Seguridad Vial (RDL 6/2015), el vehículo especial (VE) es el vehículo:",o:{a:"Autopropulsado o remolcado, concebido y construido para realizar obras o servicios determinados.",b:"Que, por sus características, está exceptuado de cumplir permanentemente los límites establecidos en el mismo para masas o dimensiones, así como la maquinaria agrícola y sus remolques.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{a:"Cierto.",b:"Cierto.",c:"Correcto: ambas.",d:"Las dos son ciertas."}},
{n:64,q:"De las definiciones contenidas en el Anexo I de la Ley de Seguridad Vial (RDL 6/2015), indique cual de las siguientes es incorrecta:",o:{a:"Motocultor: Vehículo especial autopropulsado, de dos o más ejes, dirigible por manceras por un conductor que marche a pie.",b:"Tractocarro: Vehículo especial autopropulsado, de dos o más ejes, especialmente concebido para el transporte en campo de productos agrícolas.",c:"Tractor agrícola: Vehículo especial autopropulsado, de dos o más ejes, especialmente concebido para efectuar trabajos agrícolas.",d:"Máquina agrícola automotriz: Vehículo especial autopropulsado, de dos o más ejes, concebido y construido para efectuar trabajos agrícolas."},correct:"a",why:{a:"Cierto.",b:"Cierto.",c:"Incorrecto: el tractor agrícola está definido de forma diferente; arrastra, no es especialmente concebido para 'efectuar trabajos'.",d:"Cierto."}},
{n:65,q:"De las definiciones contenidas en el Anexo I de la Ley de Seguridad Vial (RDL 6/2015), indique cual de las siguientes es incorrecta:",o:{a:"Portador: Vehículo especial autopropulsado, de dos o más ejes, concebido y construido para portar máquinas agrícolas.",b:"Máquina agrícola remolcada: Vehículo especial de maquinaria agrícola que, para trasladarse y maniobrar debe ser arrastrado o empujado por un tractor agrícola, motocultor, portador o máquina agrícola automotriz.",c:"Motocultor: Vehículo especial autopropulsado, de dos o más ejes, dirigible por manceras por un conductor que marche a pie. Ciertos motocultores pueden, también, ser dirigidos desde un asiento incorporado a un remolque o máquina agrícola o a un apero o bastidor auxiliar con ruedas.",d:"Remolque agrícola: Vehículo especial de transporte construido y destinado para ser arrastrado por un tractor agrícola, motocultor, portador o máquina agrícola automotriz. Se incluyen en esta definición a los semirremolques agrícolas."},correct:"a",why:{a:"Incorrecto: el Portador está definido de otra manera en el Anexo I.",b:"Cierto.",c:"Cierto.",d:"Cierto."}},
{n:66,q:"Según las definiciones contenidas en el Anexo I de la Ley de Seguridad Vial (RDL 6/2015):",o:{a:"Máquina agrícola remolcada: Vehículo especial de maquinaria agrícola que, para trasladarse y maniobrar debe ser arrastrado o empujado por un tractor agrícola, motocultor, portador o máquina agrícola automotriz.",b:"La definición de máquina agrícola remolcada se excluyen los aperos agrícolas que, para efectuar trabajos de preparación del terreno o laboreo, así como también, no se consideran vehículos aquellos que, además, no se consideren máquinas agrícolas remolcadas de menos de 750 kilogramos de masa.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"a",why:{a:"Correcto: definición literal de máquina agrícola remolcada.",b:"La redacción es incorrecta.",c:"La b tiene errores.",d:"La a sí es correcta."}},
{n:67,q:"En el Anexo I de la Ley de Seguridad Vial (RDL 6/2015), la máquina agrícola remolcada se define como:",o:{a:"El vehículo especial concebido y construido para el transporte, para trasladarse y maniobrar debe ser arrastrado o empujado por un tractor agrícola, motocultor, portador o máquina agrícola automotriz.",b:"El vehículo especial autopropulsado, de dos o más ejes, especialmente concebido para el transporte en campo.",c:"El vehículo especial autopropulsado, de dos o más ejes, concebido y construido para trabajos agrícolas.",d:"El vehículo especial autopropulsado, de dos o más ejes, especialmente concebido para portar máquinas agrícolas."},correct:"a",why:{a:"Correcto: debe ser arrastrada por tractor agrícola u otro.",b:"No: no es autopropulsado.",c:"No.",d:"No."}},
{n:68,q:"De las definiciones contenidas en el Anexo I de la Ley de Seguridad Vial (RDL 6/2015), indique cual de las siguientes es incorrecta:",o:{a:"Tara: Masa del vehículo, con su equipo fijo autorizado, sin personal de servicio, pasajeros ni carga, y con su dotación completa de agua, combustible, lubricante, repuestos, herramientas y accesorios reglamentarios.",b:"Masa máxima autorizada (MMA): La masa máxima para la utilización de un vehículo con carga en circulación por las vías públicas.",c:"Masa en carga: La masa efectiva del vehículo y de su carga, excluida la masa del personal de servicio y de los pasajeros.",d:"Grupo de ejes: Los ejes que forman parte de un bogie. En el caso de dos ejes, el grupo se denominará tándem, y tándem triaxial en caso de tres ejes."},correct:"b",why:{a:"Cierto.",b:"Incorrecto: la MMA es la masa máxima para circular con carga, no la masa máxima para la utilización.",c:"Cierto.",d:"Cierto."}},
{n:69,q:"De las definiciones contenidas en el Anexo I de la Ley de Seguridad Vial (RDL 6/2015), indique cual de las siguientes es incorrecta:",o:{a:"Masa por eje: La que gravita sobre el suelo, transmitida por la totalidad de las ruedas acopladas a ese eje.",b:"Luz de carretera o de largo alcance: Luz utilizada para alumbrar la carretera en caso de niebla, nevada, tormenta o nube de polvo.",c:"Luz de posición delantera: Luz utilizada para indicar la presencia y la anchura del vehículo, cuando se le vea desde delante.",d:"Luz de posición trasera: Luz utilizada para indicar la presencia y la anchura del vehículo, cuando se le vea desde detrás."},correct:"b",why:{a:"Cierto.",b:"Incorrecto: la luz de largo alcance sirve para alumbrar la carretera a distancia, no para niebla (eso es la luz antiniebla).",c:"Cierto.",d:"Cierto."}},
{n:70,q:"De las definiciones contenidas en el Anexo I de la Ley de Seguridad Vial (RDL 6/2015), indique cual de las siguientes es incorrecta:",o:{a:"Luz de posición delantera: Luz utilizada para indicar a los demás usuarios de la vía la presencia y la anchura del vehículo, cuando se le vea desde delante.",b:"Luz indicadora de dirección: Luz utilizada para indicar a los demás usuarios de la vía que el conductor quiere cambiar de dirección hacia la derecha o hacia la izquierda.",c:"Luz de cruce o de corto alcance: Luz utilizada para alumbrar la vía por delante del vehículo, sin deslumbrar ni molestar a los conductores que vengan en sentido contrario, ni a los demás usuarios de la vía.",d:"Masa en carga: La masa efectiva del vehículo y de su carga, incluida la masa del personal de servicio y de los pasajeros."},correct:"d",why:{a:"Cierto.",b:"Cierto.",c:"Cierto.",d:"Incorrecto: la masa en carga excluye la masa del personal de servicio y los pasajeros."}},
{n:71,q:"De las definiciones contenidas en el Anexo I de la Ley de Seguridad Vial (RDL 6/2015), indique cual de las siguientes es incorrecta:",o:{a:"Catadióptrico: Dispositivo utilizado para indicar la presencia del vehículo mediante la reflexión de la luz procedente de una fuente luminosa independiente de dicho vehículo, hallándose el observador cerca de la fuente.",b:"Luz indicadora de dirección: Luz utilizada para indicar a los demás usuarios de la vía que el conductor quiere cambiar de dirección hacia la derecha o hacia la izquierda.",c:"Luz catadióptrica reflectante: Placas de matrícula reflectantes, señales reflectantes obligatorias en el ADR y demás placas y señales en determinados vehículos.",d:"Luz de marcha atrás: Luz utilizada para iluminar la vía por detrás del vehículo y para advertir a los demás usuarios de la vía que el vehículo va, o está a punto de ir, marcha atrás."},correct:"a",why:{a:"Cierto.",b:"Cierto.",c:"Incorrecto: la luz catadióptica es un dispositivo reflectante, no una luz que ilumina activamente.",d:"Cierto."}},
{n:72,q:"Según lo establecido en el Anexo I de la Ley de Seguridad Vial (RDL 6/2015), no se considerarán catadiópticos:",o:{a:"Las placas de matrícula retroreflectantes.",b:"Las placas y señales retroreflectantes que deban llevarse para cumplir la reglamentación vigente sobre la utilización de determinadas categorías de vehículos o de determinados modos de funcionamiento.",c:"Las placas y señales retroreflectantes ninguna de las placas y señales mencionadas en las respuestas anteriores.",d:"No se considerarán catadiópticos ninguna de las placas y señales mencionadas en las respuestas anteriores."},correct:"d",why:{a:"Sí se consideran catadiópticos.",b:"Sí se consideran.",c:"Confuso.",d:"Correcto: ninguna de las mencionadas en a y b se considera catadióptrico."}},
{n:73,q:"De las definiciones contenidas en el Anexo I de la Ley de Seguridad Vial (RDL 6/2015), indique cual de las siguientes es incorrecta:",o:{a:"Señal de emergencia: Funcionamiento rotatorio de las luces indicadoras de dirección del vehículo para advertir que el vehículo puede representar un peligro eventual para la seguridad vial.",b:"Luz de frenado: Luz utilizada para indicar, a los usuarios de la vía que circulan detrás del vehículo, que el conductor de éste está accionando el freno de servicio.",c:"Luz de gálibo: Luz instalada lo más cerca posible del borde exterior más elevado del vehículo y destinada claramente a indicar la anchura total del vehículo. En determinados vehículos y remolques, esta luz sirve de complemento a las luces de posición delanteras y traseras del vehículo para señalar su volumen.",d:"Luz antiniebla delantera: Luz utilizada para mejorar el alumbrado de la carretera en caso de niebla, nevada, tormenta o nube de polvo."},correct:"a",why:{a:"Incorrecto: la señal de emergencia es el funcionamiento simultáneo de TODAS las luces indicadoras de dirección.",b:"Cierto.",c:"Cierto.",d:"Cierto."}},
{n:74,q:"De las definiciones contenidas en el Anexo I de la Ley de Seguridad Vial (RDL 6/2015), indique cual de las siguientes es incorrecta:",o:{a:"Luz antiniebla trasera: Luz utilizada para hacer el vehículo más visible por detrás en caso de niebla densa.",b:"Luz de alumbrado interior: Luz destinada a la iluminación del habitáculo del vehículo en forma tal que no produzca deslumbramiento ni moleste indebidamente a los demás usuarios de la vía.",c:"Luz de estacionamiento: Luz utilizada para señalizar la presencia de un vehículo estacionado en zona edificada, sin que en tales circunstancias pueda sustituir a las luces de posición delanteras y traseras.",d:"Señal de emergencia: El funcionamiento simultáneo de todas las luces indicadoras de dirección del vehículo para advertir que el vehículo puede representar un peligro eventual para la seguridad vial."},correct:"c",why:{a:"Cierto.",b:"Cierto.",c:"Incorrecto: la luz de estacionamiento SÍ puede sustituir a las de posición en determinadas circunstancias.",d:"Cierto."}},
{n:75,q:"De las definiciones contenidas en el Anexo I de la Ley de Seguridad Vial (RDL 6/2015), indique cual de las siguientes es incorrecta:",o:{a:"Plataforma: Zona de la carretera dedicada a la utilización de vehículos y demás usuarios, formada por la calzada, carriles, isletas y arcenes.",b:"Calzada: Parte de la carretera dedicada a la circulación de vehículos. Se compone de un cierto número de carriles.",c:"Carril: Banda longitudinal en que puede estar subdividida la calzada, delimitada o no por marcas viales longitudinales, siempre que tenga una anchura suficiente para permitir la circulación de una fila de automóviles sin que sean motocicletas.",d:"Carril para vehículos con alta ocupación: Aquel especialmente reservado o habilitado para la circulación de los vehículos con alta ocupación."},correct:"a",why:{a:"Incorrecto: la plataforma no incluye las isletas.",b:"Cierto.",c:"Cierto.",d:"Cierto."}},
{n:76,q:"De las definiciones contenidas en el Anexo I de la Ley de Seguridad Vial (RDL 6/2015), indique cual de las siguientes es incorrecta:",o:{a:"Acera: Zona longitudinal de la carretera elevada o no, destinada al tránsito de peatones.",b:"Refugio: Parte de la vía, elevada o delimitada de otra forma, reservada a la circulación de peatones. Se incluye en esta definición el andén y el paseo.",c:"Luz de estacionamiento: Luz utilizada para señalizar la presencia de un vehículo estacionado en zona edificada. En tales circunstancias sustituye a las luces de posición delanteras y traseras.",d:"Plataforma: Zona de la carretera dedicada al uso de vehículos, formada por la calzada y los arcenes."},correct:"b",why:{a:"Cierto.",b:"Cierto.",c:"Incorrecto: la luz de estacionamiento no sustituye siempre a las luces de posición.",d:"Cierto."}},
{n:77,q:"De las definiciones contenidas en el Anexo I de la Ley de Seguridad Vial (RDL 6/2015), indique cual de las siguientes es incorrecta:",o:{a:"Refugio: Zona peatonal situada en la calzada y protegida del tránsito rodado.",b:"Arcén: Franja longitudinal afirmada contigua a la calzada, no destinada al uso de automóviles, más que en circunstancias excepcionales.",c:"Nudo de la red viaria en el que todos los cruces de trayectorias posibles de los vehículos que lo utilizan se realizarán, preferentemente, a nivel.",d:"Zona peatonal: Parte de la vía, elevada o delimitada de otra forma, reservada a la circulación de peatones. No tendrán la consideración de travesías aquellos tramos de carretera que dispongan de una alternativa viaria o variante a la cual tiene acceso."},correct:"c",why:{a:"Cierto.",b:"Cierto.",c:"Incorrecto: la definición de intersección dice «donde los cruces se realizarán preferentemente a nivel» pero la redacción no es completa como definición.",d:"Cierto."}},
{n:78,q:"De las definiciones contenidas en el Anexo I de la Ley de Seguridad Vial (RDL 6/2015), indique cual de las siguientes es incorrecta:",o:{a:"Glorieta: Tipo común de intersección caracterizado por que en él confluyen se comunican a través de uno o varios anillos en los que se establece una circulación rotatoria alrededor de una isleta central.",b:"Paso a nivel: Cruce a la misma altura entre una vía y una línea de ferrocarril con plataforma independiente.",c:"Intersección: Nudo de la red viaria en el que todos los cruces de trayectorias posibles de los vehículos que lo utilizan se realizarán, salvo en los tramos en travesía.",d:"Carretera: Vía pública pavimentada situada fuera de poblado, salvo los tramos en travesía."},correct:"a",why:{a:"Incorrecto: la glorieta se comunica a través de uno o varios anillos, pero no «se comunican»; la redacción es incorrecta.",b:"Cierto.",c:"Cierto.",d:"Cierto."}},
{n:79,q:"Según lo establecido en el Anexo I de la Ley de Seguridad Vial (RDL 6/2015), Autopista es la carretera especialmente proyectada, construida y señalizada como tal para la exclusiva circulación de automóviles y que tiene como características:",o:{a:"No tener acceso a las propiedades colindantes.",b:"No cruzar a nivel ninguna otra senda, vía, línea de ferrocarril o tranvía, ni ser cruzada a nivel por senda, vía de comunicación o servidumbre de paso alguna.",c:"Constar de distintas calzadas para cada sentido de circulación, separadas entre sí, salvo en puntos singulares o con carácter temporal, por una franja de terreno no destinada a la circulación, o por otros medios.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{a:"Cierto.",b:"Cierto.",c:"Cierto.",d:"Correcto: las tres."}},
{n:80,q:"Según lo establecido en el Anexo I de la Ley de Seguridad Vial (RDL 6/2015), Autovía es la carretera especialmente proyectada, construida y señalizada como tal que tiene como característica:",o:{a:"No tener acceso a ella las propiedades colindantes.",b:"No cruzar a nivel ninguna otra senda, vía, línea de ferrocarril o tranvía, ni ser cruzada a nivel por senda, vía de comunicación o servidumbre de paso alguna.",c:"Constar de distintas calzadas para cada sentido de circulación, separadas entre sí, salvo en puntos singulares o con carácter temporal, por una franja de terreno no destinada a la circulación, o por otros medios.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{a:"Cierto.",b:"Cierto.",c:"Cierto.",d:"Correcto: las tres (a diferencia de la autopista no tiene acceso limitado pero sí las otras características)."}},
{n:81,q:"Según lo establecido en las definiciones del Anexo I de la Ley de Seguridad Vial (RDL 6/2015):",o:{a:"Glorieta es un tipo especial de intersección caracterizado porque en él confluyen se comunican a través de uno o varios anillos en el que se establece una circulación rotatoria alrededor de una isleta central.",b:"No son glorietas propiamente dichas las denominadas glorietas partidas en las que dos tramos, generalmente opuestos, se conectan directamente a través de la isleta central, por lo que el tráfico pasa de uno a otro y no la rodea.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{a:"Cierto.",b:"Cierto.",c:"Correcto: ambas.",d:"Las dos son ciertas."}},
{n:82,q:"De las definiciones contenidas en el Anexo I de la Ley de Seguridad Vial (RDL 6/2015), indique cual de las siguientes es incorrecta:",o:{a:"Vía para automóviles: Vía reservada exclusivamente a la circulación de automóviles, con una sola calzada y con limitación total de accesos a las propiedades colindantes, y señalizada con las señales S-5 y S-6, respectivamente.",b:"Carretera convencional: Carretera que no reúne las características propias de las autopistas, autovías y vías para automóviles.",c:"Poblado: Espacio que comprende edificios y en cuyas vías de entrada y de salida están colocadas, respectivamente, las señales de entrada a poblado y de salida de poblado.",d:"Travesía: Tramo de carretera que discurre por poblado. No tendrán la consideración de travesías aquellos tramos que dispongan de una alternativa viaria o variante a la cual tiene acceso."},correct:"a",why:{a:"Incorrecto: las vías para automóviles no tienen calzada única; pueden tener más de una.",b:"Cierto.",c:"Cierto.",d:"Cierto."}},
{n:83,q:"De las definiciones contenidas en el Anexo I de la Ley de Seguridad Vial (RDL 6/2015), indique cual de las siguientes es incorrecta:",o:{a:"Vía interurbana: Vía pública situada fuera de poblado.",b:"Vía urbana: Vía pública situada dentro de poblado, excepto las travesías.",c:"Vía ciclista: Vía específicamente acondicionada para el tráfico de ciclos, señalizada con las señales S-3 y S-4, y cuyo ancho permite el paso seguro de estos vehículos.",d:"Carril-bici: Vía ciclista que discurre adosada a la calzada, en un solo sentido o en doble sentido."},correct:"c",why:{a:"Cierto.",b:"Cierto.",c:"Incorrecto: las señales de vía ciclista son S-5 y S-6, no S-3 y S-4.",d:"Cierto."}},
{n:84,q:"De las definiciones contenidas en el Anexo I de la Ley de Seguridad Vial (RDL 6/2015), indique cual de las siguientes es incorrecta:",o:{a:"Acera ciclista: Vía ciclista que discurre por la acera.",b:"Pista bici: Vía ciclista segregada de la calzada.",c:"Carril multimodal: Carril reservado a varios tipos de vehículos o usos.",d:"Senda ciclable: Vía ciclista en la que se permite el tráfico tanto de ciclos como de peatones."},correct:"a",why:{a:"Incorrecto: la «acera ciclista» no existe con esa denominación en el Anexo I de la LSV.",b:"Cierto.",c:"Cierto.",d:"Cierto."}},
{n:85,q:"De las definiciones contenidas en el Anexo I de la Ley de Seguridad Vial (RDL 6/2015), indique cual de las siguientes es incorrecta:",o:{a:"Detención: Inmovilización de un vehículo por emergencia, por necesidades de la circulación o para cumplir algún precepto reglamentario.",b:"Intersección: Nudo de la red viaria en el que los cruces de las trayectorias posibles de los vehículos que lo utilizan se realizarán, preferentemente, a nivel.",c:"Vía ciclista: Vía específicamente acondicionada para el tráfico de ciclos, con la señalización horizontal y vertical correspondiente, y cuyo ancho permite el paso seguro de estos vehículos.",d:"Estacionamiento: Inmovilización de un vehículo que no se encuentra en situación de detención o parada."},correct:"b",why:{a:"Coincide con el Anexo I.",b:"La definición legal incluye «en el que se cruzan o convergen físicamente dos o más tramos viarios» y usa «se realizan» (presente), no «se realizarán».",c:"Coincide con el Anexo I.",d:"Coincide con el Anexo I."}},
{n:86,q:"De las definiciones contenidas en el Anexo I de la Ley de Seguridad Vial (RDL 6/2015), indique cual de las siguientes es incorrecta:",o:{a:"Vía para automóviles: Vía reservada exclusivamente a la circulación de automóviles, con una sola calzada y con limitación total de accesos a las propiedades colindantes, y señalizada con las señales S-3 y S-4, respectivamente.",b:"Refugio: Parte de la vía, elevada o delimitada de otra forma, reservada a la protección de peatones. Se incluye en esta definición el andén y el paseo.",c:"Parada: Inmovilización de un vehículo durante un tiempo inferior a dos minutos, sin que el conductor pueda abandonarlo.",d:"Carril-bici protegido: Carril-bici provisto de elementos laterales que lo separan físicamente del resto de la calzada, así como de la acera"},correct:"b",why:{a:"⚠ Mi respuesta inicial (incorrecta): Las señales S-3 y S-4 corresponden a Autovía / Fin de autovía, no a Vía para automóviles.",b:"✓ Respuesta oficial. Coincide con el Anexo I.",c:"Coincide con el Anexo I.",d:"Coincide con el Anexo I."}},
{n:87,q:"\"Ejercicio y coordinación de las competencias sobre tráfico, circulación de vehículos a motor y seguridad vial\" es el epígrafe:",o:{a:"Del Preámbulo de la Ley de Seguridad Vial (RDL 6/2015).",b:"Del Título Preliminar de la Ley de Seguridad Vial (RDL 6/2015).",c:"Del Título I de la Ley de Seguridad Vial (RDL 6/2015).",d:"Del Título II de la Ley de Seguridad Vial (RDL 6/2015)."},correct:"c",why:{a:"El Preámbulo es exposición de motivos.",b:"El Título Preliminar regula objeto y ámbito.",c:"Correcto: Título I LSV.",d:"El Título II son normas de comportamiento."}},
{n:88,q:"Según el art.149.21ª de la Constitución Española de 1978, el tráfico y la circulación de vehículos a motor:",o:{a:"Es competencia exclusiva del Estado.",b:"Es competencia exclusiva del Ministerio del Interior.",c:"Es competencia exclusiva de las Comunidades Autónomas.",d:"Todas las respuestas anteriores son incorrectas."},correct:"a",why:{a:"Correcto: art.149.1.21ª CE.",b:"El MI ejerce competencias del Estado, no es titular.",c:"La CE lo reserva al Estado.",d:"La a es correcta."}},
{n:89,q:"En materia de tráfico, además de las competencias atribuidas al Ministerio del Interior, ostentan algunas facultades los Ministerios de:",o:{a:"Industria y Energía, Fomento, Educación y Cultura.",b:"Economía y Hacienda.",c:"Sanidad y Consumo.",d:"Todos los Ministerios citados en las respuestas anteriores."},correct:"d",why:{a:"Parcial.",b:"Parcial.",c:"Parcial.",d:"Todos esos Ministerios tienen facultades."}},
{n:90,q:"Son Comunidades Autónomas que han asumido determinadas competencias de ejecución de la normativa estatal en materia de tráfico:",o:{a:"Las Comunidades de País Vasco, Cataluña y Valencia.",b:"Las Comunidades de Navarra, País Vasco y Cataluña.",c:"Las Comunidades de Andalucía, País Vasco y Cataluña.",d:"Las Comunidades de Navarra, País Vasco, Cataluña y Valencia."},correct:"b",why:{a:"Valencia no las ha asumido.",b:"Correcto: las tres tienen cuerpos policiales propios con competencias asumidas.",c:"Andalucía no las ha asumido.",d:"Valencia no figura."}},
{n:91,q:"\"Ejercicio y coordinación de las competencias sobre tráfico, circulación de vehículos a motor y seguridad vial\" es el epígrafe del Título I de la Ley de Seguridad Vial (RDL 6/2015), que dedica:",o:{a:"Su Capítulo Primero a las competencias.",b:"Su Capítulo Segundo al Consejo Superior de Tráfico, Seguridad Vial y Movilidad Sostenible",c:"Su Capítulo Tercero a la Conferencia Sectorial de Tráfico, Seguridad Vial y Movilidad Sostenible",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{a:"Parcial.",b:"Parcial.",c:"Parcial.",d:"El Título I distribuye sus tres capítulos así."}},
{n:92,q:"Sin perjuicio de las competencias que tengan asumidas las Comunidades Autónomas, y además de las que expresamente tiene atribuidas el Ministerio del Interior, según establece el art.4 de la Ley de Seguridad Vial (RDL 6/2015), corresponderá a la Administración General del Estado:",o:{a:"Expedir y revisar los permisos y licencias de conducción, así como su anulación, intervención, revocación y suspensión, en su caso.",b:"La suscripción de acuerdos y tratados internacionales sobre seguridad en los vehículos y de sus partes y piezas, así como dictar las disposiciones necesarias para su implantación en España.",c:"El canje de los permisos de conducir expedidos en el extranjero y en el ámbito militar o policial, cuando así lo prevea la legislación vigente.",d:"Todo lo descrito en las respuestas anteriores."},correct:"b",why:{a:"Parcial.",b:"✓ Respuesta oficial. Parcial.",c:"Parcial.",d:"⚠ Mi respuesta inicial (incorrecta): Las tres son AGE (art.4 LSV)."}},
{n:93,q:"La determinación de las drogas que pueden afectar a la conducción, las pruebas para su detección y sus niveles máximos, es una competencia que corresponde:",o:{a:"A la Administración General del Estado, sin perjuicio de las competencias que tengan asumidas las Comunidades Autónomas.",b:"A la Administración del Estado exclusivamente.",c:"A las Comunidades Autónomas.",d:"Todas las respuestas anteriores son incorrectas."},correct:"a",why:{a:"Correcto (art.4 LSV).",b:"No es «exclusiva»: hay reserva de CCAA.",c:"No es propia de CCAA.",d:"La a es correcta."}},
{n:94,q:"Sin perjuicio de las competencias que tengan asumidas las Comunidades Autónomas, y además de las que expresamente tiene atribuidas el Ministerio del Interior, según establece el art.4 de la Ley de Seguridad Vial (RDL 6/2015), corresponderá a la Administración General del Estado:",o:{a:"La retirada de vehículos de la vía fuera de poblado y la baja, temporal o definitiva, de la circulación de los mismos.",b:"Expedir autorizaciones o permisos temporales para la circulación de vehículos.",c:"La determinación del cuadro de las enfermedades y discapacidades que inhabilitan para conducir.",d:"Todo lo descrito en las respuestas anteriores."},correct:"c",why:{a:"Parcial.",b:"Parcial.",c:"✓ Respuesta oficial. Parcial.",d:"⚠ Mi respuesta inicial (incorrecta): Las tres son AGE (art.4 LSV)."}},
{n:95,q:"Sin perjuicio de las competencias que tengan asumidas las Comunidades Autónomas, corresponderá a la Administración General del Estado:",o:{a:"La determinación de los requisitos sanitarios mínimos para efectuar los reconocimientos para la detección de enfermedades y discapacidades que inhabilitan para conducir.",b:"La inspección, control y, en su caso, suspensión o cierre de los establecimientos dedicados a efectuar los reconocimientos citados en la respuesta anterior.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{a:"Parcial.",b:"Parcial.",c:"Ambas son AGE (art.4 LSV).",d:"Las dos son ciertas."}},
{n:96,q:"Sin perjuicio de las competencias que tengan asumidas las Comunidades Autónomas, corresponderá a la Administración General del Estado:",o:{a:"La facultad de determinar la normativa técnica básica que afecte de manera directa a la seguridad vial.",b:"La previa homologación, en su caso, de los elementos de los vehículos, remolques y semirremolques que afecten a la seguridad vial.",c:"La aprobación de las normas básicas y mínimas para la programación de la educación vial para la movilidad segura y sostenible, en las distintas modalidades de la enseñanza, incluyendo la formación en conducción ciclista y en vehículos de movilidad personal.",d:"Todo lo descrito en las respuestas anteriores."},correct:"d",why:{a:"Parcial.",b:"Parcial.",c:"Parcial.",d:"Las tres son AGE (art.4 LSV)."}},
{n:97,q:"La facultad de dictar instrucciones y directrices en materia de inspección técnica de vehículos es una competencia que corresponde:",o:{a:"A la administración General del Estado en todo caso.",b:"A la administración General del Estado, sin perjuicio de las competencias que tengan asumidas las Comunidades Autónomas.",c:"A las Comunidades Autónomas.",d:"Ninguna de las respuestas anteriores es correcta."},correct:"b",why:{a:"No es «en todo caso».",b:"Correcto: art.4 LSV.",c:"No es propia de CCAA.",d:"La b es correcta."}},
{n:98,q:"Con respecto a la prestación de la asistencia sanitaria en las vías públicas o de uso público, corresponde a la Administración General del Estado:",o:{a:"La coordinación.",b:"La homologación.",c:"La realización de este servicio de manera directa.",d:"La realización de este servicio de manera diferida."},correct:"a",why:{a:"Correcto (art.4 LSV): la AGE coordina.",b:"No es el término legal.",c:"No es prestación directa.",d:"«Diferida» no es término legal."}},
{n:99,q:"Sin perjuicio de las competencias que tengan asumidas las Comunidades Autónomas, corresponderá a la Administración General del Estado:",o:{a:"La regulación del transporte de personas, y especialmente el transporte escolar y de menores, a los efectos relacionados con la seguridad vial.",b:"La regulación del transporte de mercancías, especialmente el de mercancías peligrosas, perecederas y contenedores, de acuerdo con la reglamentación internacional, a los efectos relacionados con la seguridad vial.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{a:"Parcial.",b:"Parcial.",c:"Ambas son AGE.",d:"Las dos son ciertas."}},
{n:100,q:"La regulación de aquellas actividades industriales que tengan una incidencia directa sobre la seguridad vial y, en especial, la de los talleres de reparación de vehículos, es una competencia que corresponde:",o:{a:"A la Administración del Estado en todo caso.",b:"A la Administración General del Estado, sin perjuicio de las competencias que tengan asumidas las Comunidades Autónomas.",c:"A las Comunidades Autónomas.",d:"Ninguna de las respuestas anteriores es correcta."},correct:"b",why:{a:"No es «en todo caso».",b:"Correcto: art.4 LSV.",c:"No es propia de CCAA.",d:"La b es correcta."}},
{n:101,q:"La regulación del vehículo automatizado, de conformidad con lo dispuesto en la ley, es una competencia que corresponde:",o:{a:"A la Administración del Estado en todo caso.",b:"A la Administración General del Estado, sin perjuicio de las competencias que tengan asumidas las Comunidades Autónomas.",c:"Al Ministerio de Interior.",d:"A las Comunidades Autónomas."},correct:"b",why:{a:"No es «en todo caso».",b:"Correcto: art.4 LSV.",c:"No es solo del MI.",d:"No es propia de CCAA."}},
{n:102,q:"Sin perjuicio de las competencias que tengan asumidas las CCAA y de las que corresponden a la Administración General del Estado, al Ministerio del Interior le corresponden las establecidas:",o:{a:"En el art.4 de la Ley de Seguridad Vial (RDL 6/2015).",b:"En el art.5 de la Ley de Seguridad Vial (RDL 6/2015).",c:"En el art.6 de la Ley de Seguridad Vial (RDL 6/2015).",d:"En el art.7 de la Ley de Seguridad Vial (RDL 6/2015)."},correct:"b",why:{a:"Art.4 regula AGE.",b:"Correcto: art.5 regula competencias del MI.",c:"Art.6: Guardia Civil.",d:"Art.7: municipios."}},
{n:103,q:"Respecto a los cursos de sensibilización y reeducación vial que han de realizar los conductores como consecuencia de la pérdida parcial o total de los puntos que les hayan sido asignados, las competencias del Ministerio del Interior están referidas a:",o:{a:"Impartir estos cursos.",b:"Contratar la gestión de estos cursos.",c:"Llevar a cabo la vigilancia y control del personal encargado de impartir estos cursos.",d:"Todas las respuestas anteriores son correctas."},correct:"b",why:{a:"Parcial.",b:"✓ Respuesta oficial. Parcial.",c:"Parcial.",d:"⚠ Mi respuesta inicial (incorrecta): El MI tiene atribuidas las tres."}},
{n:104,q:"Respecto a los cursos de sensibilización y reeducación vial que han de realizar los conductores como consecuencia de la pérdida parcial o total de los puntos que les hayan sido asignados, las competencias del Ministerio del Interior están referidas a:",o:{a:"Elaborar el contenido de estos cursos.",b:"Determinar la duración y requisitos de estos cursos.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{a:"Parcial.",b:"Parcial.",c:"Ambas son del MI (art.5 LSV).",d:"Las dos son ciertas."}},
{n:105,q:"De las competencias que corresponden al Ministerio del Interior, reguladas en el art.5 de la Ley de Seguridad Vial (RDL 6/2015), indique cual de las siguientes es incorrecta:",o:{a:"La expedición y revisión de los permisos y licencias para conducir vehículos a motor y ciclomotores y de la autorización especial para conducir vehículos que transporten mercancías peligrosas, con los requisitos sobre conocimientos, aptitudes técnicas y psicofísicas y periodicidad que se determinen reglamentariamente, así como la declaración de la nulidad, lesividad o pérdida de vigencia de aquéllos.",b:"La matriculación, expedición y registro de los permisos de circulación de los vehículos a motor, remolques, semirremolques, ciclomotores y vehículos de movilidad personal, así como la declaración de nulidad, lesividad o pérdida de vigencia de dichos permisos, en los términos previstos en esta ley.",c:"El canje, de acuerdo con las normas reglamentarias aplicables, de los permisos de conducción y de la autorización especial para conducir vehículos que transporten mercancías peligrosas expedidos en el ámbito militar y policial por los correspondientes en el ámbito civil, así como el canje, la inscripción o la renovación de los permisos expedidos en el extranjero cuando así lo prevea la legislación vigente.",d:"Las autorizaciones de apertura de centros de formación de conductores y la declaración de nulidad, lesividad o pérdida de vigencia de aquéllas, así como los certificados de aptitud y autorizaciones que permitan acceder a la actuación profesional en materia de enseñanza de la conducción y la acreditación de la destinada al reconocimiento de las aptitudes psicofísicas de los conductores, con los requisitos y condiciones que reglamentariamente se determinen."},correct:"b",why:{a:"Competencia art.5.",b:"✓ Respuesta oficial. Competencia art.5.",c:"Competencia art.5.",d:"⚠ Mi respuesta inicial (incorrecta): El MI autoriza centros de reconocimiento (aptitudes psicofísicas), no centros de formación de conductores."}},
{n:106,q:"De las competencias que corresponden al Ministerio del Interior, reguladas en el art.5 de la Ley de Seguridad Vial (RDL 6/2015), indique cual de las siguientes es incorrecta:",o:{a:"Los registros de vehículos, de conductores e infractores, de profesionales de la enseñanza de la conducción, de centros de formación de conductores, de los centros de reconocimiento destinados a verificar las aptitudes físicas y psicofísicas de los conductores y de manipulación de placas de matrícula, en los términos previstos en esta ley.",b:"Las autorizaciones o permisos temporales y provisionales para la circulación de vehículos.",c:"Las normas especiales que posibiliten la circulación de vehículos históricos y fomenten la conservación o restauración de los que integran el patrimonio histórico.",d:"La retirada de los vehículos de la vía fuera de poblado y la baja temporal o definitiva de la circulación de dichos vehículos."},correct:"a",why:{a:"✓ Respuesta oficial. Competencia MI.",b:"Competencia MI.",c:"Competencia MI.",d:"⚠ Mi respuesta inicial (incorrecta): La retirada «fuera de poblado» es competencia AGE del art.4, no específicamente del MI en el art.5."}},
{n:107,q:"La anulación, intervención, revocación y suspensión de los permisos y licencias para conducir corresponde:",o:{a:"A los Tribunales de Justicia.",b:"Al Ministerio del Interior.",c:"A la Consellería competente de las Comunidades Autónomas.",d:"Las respuestas b y c son correctas."},correct:"b",why:{a:"Los Tribunales actúan en casos judiciales.",b:"✓ Respuesta oficial. Parcial: en CCAA con competencias, lo hace la Consellería.",c:"Parcial: con carácter general lo hace el MI.",d:"⚠ Mi respuesta inicial (incorrecta): Correcto: MI y, en su caso, Consellería autonómica."}},
{n:108,q:"De las competencias que corresponden al Ministerio del Interior, reguladas en el art.5 de la Ley de Seguridad Vial (RDL 6/2015), indique cual de las siguientes es incorrecta:",o:{a:"La vigilancia y disciplina del tráfico en toda clase de vías interurbanas y en travesías cuando no exista policía local, así como la denuncia y sanción de las infracciones a las normas de circulación y de seguridad en dichas vías.",b:"La denuncia, registro y sanción de las infracciones por incumplimiento de la obligación de someterse a la inspección técnica de vehículos, así como a las prescripciones derivadas de aquélla, y por razón del ejercicio de actividades industriales que afecten de manera directa o indirecta a la seguridad vial.",c:"La regulación, ordenación y gestión del tráfico en vías interurbanas y en travesías, estableciendo para estas últimas fórmulas de cooperación o delegación con las Entidades Locales, y sin perjuicio de lo establecido en otras disposiciones y de las facultades de otros departamentos ministeriales.",d:"Las directrices básicas y esenciales para la formación y actuación de los agentes de la autoridad encargados de la vigilancia del tráfico, sin perjuicio de las atribuciones de las corporaciones locales, con cuyos órganos se instrumentará, de común acuerdo, la colaboración necesaria."},correct:"b",why:{a:"Competencia art.5.",b:"Añade «registro» (no está en la ley) y «o indirecta» (la ley dice solo «directa»).",c:"Competencia art.5.",d:"Competencia art.5."}},
{n:109,q:"La competencia del Ministerio del Interior en cuanto a la autorización de pruebas deportivas que discurran por vías públicas comprende:",o:{a:"La de aquellas pruebas que utilicen cualquier tipo de vías públicas o de uso público.",b:"La de aquellas pruebas que utilicen carreteras estatales en todo o parte del recorrido o en travesías.",c:"La de aquellas pruebas que utilicen vías abiertas al tráfico.",d:"La de aquellas pruebas que discurran por la red de carreteras del Estado, o por aquellas otras vías que, siendo titularidad de otras administraciones, el Estado tenga atribuida la vigilancia y regulación del tráfico."},correct:"b",why:{a:"Demasiado amplio.",b:"Correcto: art.5 LSV (carreteras estatales o travesías).",c:"No coincide con la formulación legal.",d:"Es otra formulación; la típica del art.5 es la b."}},
{n:110,q:"En el caso de pruebas deportivas que discurran por vías públicas o de uso público en las que la Administración General del Estado tenga atribuida la vigilancia y regulación del tráfico, corresponde al Ministerio del Interior:",o:{a:"Su autorización.",b:"Informarlas con carácter vinculante.",c:"Informarlas con carácter no vinculante.",d:"La vigilancia y control de su celebración."},correct:"b",why:{a:"⚠ Mi respuesta inicial (incorrecta): Correcto: cuando el Estado vigila esa vía, el MI autoriza.",b:"✓ Respuesta oficial. El informe vinculante es para vías de otras Admin.",c:"No es informe.",d:"Vigilar es consecuencia; la facultad es autorizar."}},
{n:111,q:"De las competencias que corresponden al Ministerio del Interior, reguladas en el art.5 de la Ley de Seguridad Vial (RDL 6/2015), indique cual de las siguientes es incorrecta:",o:{a:"La autorización de pruebas deportivas que tengan que celebrarse utilizando en todo o parte del recorrido carreteras locales, estatales o travesías, previo informe de las Administraciones titulares de las vías públicas afectadas, e informar, con carácter potestativo, las que vayan a conceder otros órganos autonómicos o municipales por ser de su competencia.",b:"La matriculación y expedición de los permisos de circulación de los vehículos a motor, remolques, semirremolques y ciclomotores, así como la declaración de nulidad, lesividad o pérdida de vigencia de dichos permisos, en los términos que reglamentariamente se determine.",c:"Los registros de vehículos, de conductores e infractores, de profesionales de la enseñanza de la conducción, de centros de formación de conductores, de los centros de reconocimiento destinados a verificar las aptitudes psicofísicas de los conductores y de manipulación de placas de matrícula, en los términos que reglamentariamente se determine.",d:"La denuncia y sanción de las infracciones por incumplimiento de la obligación de someterse a la inspección técnica de vehículos, así como a las prescripciones derivadas de aquélla, y por razón del ejercicio de actividades industriales que afecten de manera directa a la seguridad vial."},correct:"a",why:{a:"Doble error: la ley dice «estatales o travesías» (no «locales») y el informe es «vinculante», no «potestativo».",b:"Competencia art.5.",c:"Competencia art.5.",d:"Competencia art.5."}},
{n:112,q:"La competencia para conceder certificados de aptitud y autorizaciones que permitan ejercer la actuación profesional en materia de la enseñanza de la conducción, corresponde a:",o:{a:"El Ministerio del Interior.",b:"El Ministerio de Industria.",c:"El Ministerio de Fomento.",d:"El Ministerio de Educación y Ciencia."},correct:"a",why:{a:"Correcto: art.5 LSV.",b:"Industria no.",c:"Fomento no.",d:"Educación no."}},
{n:113,q:"De las competencias que corresponden al Ministerio del Interior, reguladas en el art.5 de la Ley de Seguridad Vial (RDL 6/2015), indique cual de las siguientes es incorrecta:",o:{a:"El cierre a la circulación de carreteras o tramos de ellas por razones de seguridad o fluidez del tráfico o la restricción en ellas del acceso de determinados vehículos por motivos medioambientales, en los términos que reglamentariamente se determine.",b:"La coordinación de la estadística y la investigación de accidentes de tráfico, así como las estadísticas de inspección técnica de vehículos, en los términos que se determinen en esta ley.",c:"La realización de las pruebas, reglamentariamente establecidas, para determinar el grado de intoxicación alcohólica, o por drogas, de los conductores que circulen por las vías públicas en las que tiene atribuida la ordenación, gestión, control y vigilancia del tráfico.",d:"La garantía de igualdad de oportunidades, no discriminación y accesibilidad universal de las personas con discapacidad, especialmente en su calidad de conductores, en todos los ámbitos regulados en esta ley."},correct:"b",why:{a:"Competencia art.5.",b:"La redacción legal incluye «en colaboración con otros organismos oficiales y privados»; aquí se omite y se cambia por «en los términos que se determinen en esta ley».",c:"Competencia art.5.",d:"Competencia art.5."}},
{n:114,q:"La anulación, intervención y revocación de los permisos de circulación de los vehículos a motor, remolques y semirremolques es competencia de:",o:{a:"El Ministerio del Interior.",b:"El Ministerio de Industria y Energía.",c:"El Ministerio de Transportes.",d:"El Ministerio de Fomento."},correct:"a",why:{a:"Correcto: art.5 LSV.",b:"Industria no.",c:"Transportes no.",d:"Fomento no."}},
{n:115,q:"Expedir autorizaciones o permisos temporales y provisionales para la circulación de vehículos hasta su matriculación definitiva es competencia de:",o:{a:"El Ministerio de Industria y Energía.",b:"El Ministerio de Defensa.",c:"El Ministerio del Interior.",d:"El Ministerio de Fomento."},correct:"c",why:{a:"Industria no.",b:"Defensa no.",c:"Correcto: art.5 LSV.",d:"Fomento no."}},
{n:116,q:"El establecimiento de normas especiales que posibiliten la circulación de vehículos históricos es competencia de:",o:{a:"Las Comunidades Autónomas.",b:"El Ministerio de Cultura.",c:"El Ministerio de Industria y Energía.",d:"El Ministerio del Interior."},correct:"d",why:{a:"No es de CCAA.",b:"Cultura no.",c:"Industria interviene en lo técnico, no en circulación.",d:"Correcto: art.5 LSV."}},
{n:117,q:"De las competencias que corresponden al Ministerio del Interior, reguladas en el art.5 de la Ley de Seguridad Vial (RDL 6/2015), indique cual de las siguientes es incorrecta:",o:{a:"La determinación de la duración, el contenido y los requisitos de los cursos de conducción segura y eficiente cuya realización conlleve la recuperación o bonificación de puntos, así como de los mecanismos de certificación y control de los mismos a tal efecto.",b:"La inspección de los centros y otros operadores cuya actividad esté vinculada con el ejercicio de funciones en el ámbito de las competencias establecidas en este artículo.",c:"La coordinación de la estadística y la investigación de accidentes de tráfico, así como las estadísticas de inspección técnica de vehículos, en colaboración con otros organismos oficiales y privados, en los términos que reglamentariamente se determine.",d:"La auditoría de los centros, operadores, servicios y trámites de competencia de la Administración General del Estado, con objeto de supervisar y garantizar el correcto funcionamiento y la calidad de aquéllos."},correct:"a",why:{a:"✓ Respuesta oficial. Competencia art.5.",b:"Competencia art.5.",c:"Competencia art.5 (con redacción correcta).",d:"⚠ Mi respuesta inicial (incorrecta): La ley se refiere a la auditoría de los centros «del organismo autónomo Jefatura Central de Tráfico», no «de la AGE»."}},
{n:118,q:"El establecimiento de normas que contribuyan al fomento de la conservación y restauración de los vehículos que integran el patrimonio histórico cultural, es competencia de:",o:{a:"El Ministerio del Interior.",b:"El Ministerio de Cultura.",c:"El Ministerio de Fomento.",d:"El Ministerio de Industria y Energía."},correct:"a",why:{a:"Correcto: art.5 LSV (normas para vehículos históricos).",b:"Cultura no regula circulación.",c:"Fomento no.",d:"Industria no."}},
{n:119,q:"La retirada de los vehículos de la vía fuera de poblado y la baja, temporal o definitiva, de la circulación de los mismos, es competencia:",o:{a:"De los Municipios.",b:"Del Ministerio del Interior.",c:"Del Ministerio de Obras Públicas.",d:"Del Ministerio de Transportes."},correct:"b",why:{a:"Municipios solo en suelo urbano.",b:"Correcto: art.5 LSV.",c:"Obras Públicas no.",d:"Transportes no."}},
{n:120,q:"Corresponde al Ministerio del Interior:",o:{a:"El registro de vehículos, conductores e infractores.",b:"El registro de profesionales de la enseñanza de la conducción y de centros de formación de conductores.",c:"El registro de centros de reconocimiento para conductores de vehículos a motor y de manipulación de placas de matrícula.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{a:"Parcial.",b:"Parcial.",c:"Parcial.",d:"El MI lleva todos esos registros (art.5 LSV)."}},
{n:121,q:"Según lo establecido en el art.5 de la Ley de Seguridad Vial (RDL 6/2015), sin perjuicio de las competencias que tengan asumidas las CCAA, corresponde al Ministerio del Interior:",o:{a:"La auditoría de los centros, operadores, servicios y trámites de competencia del organismo autónomo Jefatura Central de Tráfico, con objeto de supervisar y garantizar el correcto funcionamiento y la calidad de aquéllos, que se llevará a cabo, con arreglo a las normas legales que le sean de aplicación, directamente por empleados públicos formados para estas funciones, o mediante la colaboración de entidades acreditadas.",b:"De conformidad con lo dispuesto en la Ley, las normas en materia de tráfico y seguridad vial que deberán cumplir los vehículos dotados de un sistema de conducción automatizado para su circulación, a excepción de los requisitos técnicos para la homologación de los vehículos cuyo desarrollo corresponde al Ministerio competente en materia de industria.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{a:"Parcial.",b:"Parcial.",c:"Ambas son MI (art.5 LSV).",d:"Las dos son ciertas."}},
{n:122,q:"La vigilancia y disciplina del tráfico en las travesías es competencia de:",o:{a:"El Ministerio del Interior aunque exista Policía Local.",b:"El Ministerio del Interior cuando no exista Policía Local.",c:"Las Comunidades Autónomas aunque exista Policía Local.",d:"Las Comunidades Autónomas cuando no exista Policía Local."},correct:"b",why:{a:"No es «aunque exista».",b:"Correcto: art.5 LSV — MI solo cuando no haya Policía Local.",c:"No corresponde a CCAA en general.",d:"Tampoco a CCAA cuando no haya PL."}},
{n:123,q:"La denuncia y sanción de las infracciones a las normas de circulación y de seguridad en vías interurbanas es competencia de:",o:{a:"El Ministerio de Fomento.",b:"El Ministerio del Interior.",c:"El Ministerio de Administraciones Públicas.",d:"El Ministerio de Defensa."},correct:"b",why:{a:"Fomento no.",b:"Correcto: art.5 LSV.",c:"AAPP no.",d:"Defensa no."}},
{n:124,q:"La regulación del tráfico en vías interurbanas y travesías es competencia de:",o:{a:"El Ministerio de Defensa.",b:"El Ministerio de Fomento.",c:"Las Comunidades Autónomas.",d:"El Ministerio del Interior."},correct:"d",why:{a:"Defensa no.",b:"Fomento no.",c:"CCAA solo si tienen competencias asumidas.",d:"Correcto: art.5 LSV (con cooperación con EELL en travesías)."}},
{n:125,q:"La realización de las pruebas establecidas para determinar el grado de intoxicación alcohólica, o de intoxicación por estupefacientes, psicotrópicos o estimulantes a los conductores que circulen por vías públicas, es competencia atribuida al Ministerio del Interior, siempre que:",o:{a:"Se trate de carreteras de titularidad estatal.",b:"Se trate de vías abiertas al tráfico en general.",c:"El Estado tenga atribuida la vigilancia y control de la seguridad de la circulación vial en dichas vías.",d:"No se trate de vías urbanas."},correct:"c",why:{a:"No solo estatales.",b:"Demasiado amplio.",c:"Correcto: art.5 LSV — solo donde el Estado vigila el tráfico.",d:"No basta con excluir lo urbano."}},
{n:126,q:"La competencia del Ministerio del Interior en lo referente a aquellas personas con discapacidad que tengan la condición de conductores, está referida a:",o:{a:"Garantizar la igualdad de oportunidades de estas personas.",b:"Garantizar su no discriminación.",c:"Garantizar la accesibilidad universal.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{a:"Parcial.",b:"Parcial.",c:"Parcial.",d:"El MI debe garantizar las tres (art.5 LSV)."}},
{n:127,q:"Las competencias que en materia de tráfico están atribuidas al Ministerio del Interior, las ejerce a través de:",o:{a:"Los Ayuntamientos.",b:"La Jefatura Central de Tráfico.",c:"El Consejo Superior de Tráfico y Seguridad Vial.",d:"Las Consellerías competentes de cada Comunidad Autónoma."},correct:"b",why:{a:"Los Ayuntamientos tienen sus propias competencias.",b:"Correcto: el MI actúa a través del organismo autónomo Jefatura Central de Tráfico (DGT).",c:"Es órgano consultivo, no ejecutor.",d:"Las Consellerías son de las CCAA."}},
{n:128,q:"La Jefatura Central de Tráfico:",o:{a:"No existe como tal. Actualmente, sus competencias corresponden a la Dirección General de Tráfico.",b:"Es una empresa pública.",c:"Es un órgano consultivo dependiente del Ministerio del Interior.",d:"Es un organismo autónomo."},correct:"d",why:{a:"Sí existe.",b:"No es empresa pública.",c:"No es consultivo.",d:"Correcto: es un organismo autónomo (DGT)."}},
{n:129,q:"De conformidad con lo establecido en el art.6 de la Ley de Seguridad Vial (RDL 6/2015), la Guardia Civil, especialmente su Agrupación de Tráfico, en los términos que reglamentariamente se determine, actuará:",o:{a:"Para el ejercicio de las competencias atribuidas al Ministerio del Interior en materia de regulación, ordenación, gestión y vigilancia del tráfico.",b:"Para la denuncia de las infracciones a las normas contenidas en esta ley.",c:"Para las labores de protección y auxilio en las vías públicas o de uso público.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{a:"Parcial.",b:"Parcial.",c:"Parcial.",d:"Las tres son funciones de la Guardia Civil (art.6 LSV)."}},
{n:130,q:"La Guardia Civil, a efectos de llevar a cabo las actuaciones que tiene atribuidas en el art.6 de la Ley de Seguridad Vial (RDL 6/2015), depende específicamente:",o:{a:"Del Ministerio del Interior.",b:"Del organismo autónomo Jefatura Central de Tráfico.",c:"Del Destacamento de Tráfico al que pertenezca.",d:"De la Agrupación de Tráfico a la que pertenezca."},correct:"b",why:{a:"Es la dependencia general, pero para tráfico depende específicamente de la JCT.",b:"Correcto: art.6 LSV.",c:"El Destacamento es unidad de Tráfico, no la dependencia funcional.",d:"La Agrupación es la propia Guardia Civil."}},
{n:131,q:"Corresponde a los municipios la regulación, ordenación, gestión, vigilancia y disciplina del tráfico:",o:{a:"En las vías urbanas de su titularidad.",b:"En las vías urbanas e interurbanas de su titularidad.",c:"En todo tipo de vías de sus respectivos términos municipales.",d:"Todas las respuestas anteriores son incorrectas."},correct:"a",why:{a:"Correcto: art.7 LSV — solo vías urbanas de titularidad municipal.",b:"Las interurbanas no son competencia municipal.",c:"No en todo tipo de vías.",d:"La a es correcta."}},
{n:132,q:"En las vías urbanas de su titularidad, corresponde a los municipios la regulación, ordenación, gestión, vigilancia y disciplina del tráfico:",o:{a:"Cierto, realizando tal función por medio de agentes de Policía Local y Guardia Civil.",b:"Cierto, realizando tal función por medio de agentes propios.",c:"Falso, dichas competencias son exclusivas del Estado.",d:"Cierto, pero la gestión y ordenación será compartida con la Consellería competente en la materia."},correct:"b",why:{a:"No incluye a la Guardia Civil en urbanas.",b:"Correcto: por medio de agentes propios (Policía Local).",c:"No es exclusiva del Estado.",d:"No es compartida con Conselleria."}},
{n:133,q:"La denuncia y sanción de las infracciones de tráfico que se cometan en vías urbanas es competencia:",o:{a:"De los municipios en todo caso.",b:"De los municipios en el caso de que la sanción no esté expresamente atribuida a otra Administración.",c:"Del Ministerio del Interior en todo caso.",d:"Del Ministerio del Interior, salvo que la sanción esté expresamente atribuida a los municipios."},correct:"b",why:{a:"No es «en todo caso».",b:"Correcto: art.7 LSV — municipios salvo atribución expresa.",c:"No es del MI.",d:"Es al revés."}},
{n:134,q:"Corresponde a los municipios la regulación de los usos de las vías urbanas, haciendo compatible la equitativa distribución de los aparcamientos entre todos los usuarios con la necesaria fluidez del tráfico rodado y con el uso peatonal de las calles, ejerciendo tal función a través de:",o:{a:"Ordenanzas.",b:"Ordenes.",c:"Leyes",d:"Bandos."},correct:"a",why:{a:"Correcto: art.7 LSV (Ordenanzas municipales).",b:"Las órdenes no regulan.",c:"Los municipios no dictan leyes.",d:"Los bandos no son norma reguladora."}},
{n:135,q:"El establecimiento en vías urbanas de medidas de estacionamiento limitado con el fin de garantizar la rotación de los aparcamientos es competencia de:",o:{a:"El municipio.",b:"El municipio, previo dictamen de la Comunidad Autónoma.",c:"El municipio, previo dictamen del Ministerio del Interior.",d:"El municipio, previo dictamen del Consejo de Estado."},correct:"a",why:{a:"Correcto: art.7 LSV — competencia directa municipal, sin dictamen previo.",b:"No requiere dictamen autonómico.",c:"No requiere dictamen MI.",d:"No requiere dictamen del Consejo de Estado."}},
{n:136,q:"Corresponde a los municipios el establecimiento de medidas de estacionamiento limitado, con el fin de garantizar la rotación de los aparcamientos, prestando especial atención a las necesidades de las personas con discapacidad que tienen reducida su movilidad y que utilizan vehículos, todo ello con el fin de favorecer su integración social, ejerciendo tal función a través de:",o:{a:"Bandos.",b:"Leyes",c:"Ordenanzas.",d:"Ordenes."},correct:"c",why:{a:"Los bandos no.",b:"Los municipios no dictan leyes.",c:"Correcto: art.7 LSV (Ordenanzas).",d:"Las órdenes no."}},
{n:137,q:"Es competencia de los municipios:",o:{a:"La inmovilización de vehículos en vías urbanas cuando no se hallen provistos de título que habilite el estacionamiento en zonas limitadas en tiempo o excedan de la autorización concedida",b:"La inmovilización de vehículos en vías urbanas de los vehículos estacionados en zonas de estacionamiento limitado en los que no sea visible el título habilitante desde el exterior.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"a",why:{a:"✓ Respuesta oficial. Parcial.",b:"Parcial.",c:"⚠ Mi respuesta inicial (incorrecta): Ambas son competencia municipal (art.7 LSV).",d:"Las dos son ciertas."}},
{n:138,q:"La Ley de Seguridad Vial (RDL 6/2015) permite que los municipios inmovilicen aquellos vehículos que se hallen en vías urbanas, en las zonas limitadas en tiempo, desprovistos de título habilitante hasta que:",o:{a:"El conductor satisfaga el importe de la sanción.",b:"El conductor haga cesar la situación irregular del vehículo.",c:"Se logre la identificación del conductor.",d:"Se garantice el pago de la medida cautelar por cualquier medio admitido en Derecho."},correct:"c",why:{a:"No depende del pago de la sanción.",b:"⚠ Mi respuesta inicial (incorrecta): Correcto: art.7 LSV — hasta cesar la situación irregular.",c:"✓ Respuesta oficial. No depende de identificación.",d:"No es ese el criterio."}},
{n:139,q:"En las condiciones previstas para la inmovilización en el art.7 de la Ley de Seguridad Vial (RDL 6/2015), corresponde a los municipios la retirada de vehículos de las vías urbanas y el posterior depósito de aquellos, cuando obstaculicen o dificulten la circulación:",o:{a:"Cierto, así como cuando supongan un peligro para la circulación.",b:"Cierto, así como cuando los vehículos se encuentren incorrectamente aparcados en las zonas de estacionamiento restringidas.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{a:"Parcial.",b:"Parcial.",c:"Ambas son supuestos de retirada municipal (art.7 LSV).",d:"Las dos son ciertas."}},
{n:140,q:"Según lo establecido en el art.7 de la Ley de Seguridad Vial (RDL 6/2015), las bicicletas sólo podrán ser retiradas de las vías urbanas y llevadas al correspondiente depósito:",o:{a:"Si están abandonadas.",b:"Si, estando amarradas, dificultan la circulación de vehículos o personas o dañan el mobiliario urbano.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{a:"Parcial.",b:"Parcial.",c:"Ambas son los únicos supuestos legales (art.7 LSV).",d:"Las dos son ciertas."}},
{n:141,q:"La retirada de vehículos en las vías interurbanas y el posterior depósito de éstos, es competencia de los municipios:",o:{a:"En los casos y condiciones que reglamentariamente se determinen.",b:"Siempre y cuando se trate de vehículos de peso máximo autorizado igual o inferior a 3500 Kg.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"d",why:{a:"No: las interurbanas no son competencia municipal.",b:"El peso del vehículo no es criterio.",c:"Ambas son falsas.",d:"Correcto: la retirada en interurbanas no corresponde a los municipios."}},
{n:142,q:"La autorización de pruebas deportivas cuando discurran íntegra y exclusivamente por el casco urbano corresponde:",o:{a:"A los municipios.",b:"A los municipios, excepto si se trata de travesías.",c:"Al Ministerio del Interior.",d:"Al Ministerio de Obras públicas."},correct:"a",why:{a:"✓ Respuesta oficial. Si es travesía, no es municipal.",b:"⚠ Mi respuesta inicial (incorrecta): Correcto: art.7 LSV — municipios salvo travesías.",c:"El MI solo para vías que el Estado vigila.",d:"Obras Públicas no."}},
{n:143,q:"La realización de las pruebas de alcoholemia en vías urbanas es competencia de:",o:{a:"Los municipios.",b:"Los municipios, de conformidad con las directrices que determinen las Cortes Generales.",c:"Los municipios con sujeción a las directrices que determine el Gobierno.",d:"Los municipios con sujeción a los criterios emanados de las Comunidades Autónomas."},correct:"b",why:{a:"Falta el sometimiento a directrices.",b:"✓ Respuesta oficial. No son las Cortes.",c:"⚠ Mi respuesta inicial (incorrecta): Correcto: art.7 LSV — municipios con directrices del Gobierno.",d:"No son las CCAA."}},
{n:144,q:"Es competencia de los municipios:",o:{a:"El cierre de vías urbanas, cuando sea necesario.",b:"La restricción de la circulación a determinados vehículos en vías urbanas, por motivos medioambientales.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{a:"Parcial.",b:"Parcial.",c:"Ambas son competencia municipal (art.7 LSV).",d:"Las dos son ciertas."}},
{n:145,q:"Se constituye como órgano de consulta y participación para el impulso y mejora de la seguridad vial y la movilidad sostenible, y para promover la concertación de las distintas administraciones públicas y entidades que desarrollan actividades en éstos ámbitos:",o:{a:"El Consejo Superior de Tráfico.",b:"El Consejo Superior de Tráfico, Seguridad Vial y Movilidad Sostenible.",c:"La Dirección General de Tráfico.",d:"La Jefatura Central de Tráfico."},correct:"b",why:{a:"Falta «Seguridad Vial y Movilidad Sostenible».",b:"Correcto: art.8 LSV — denominación completa.",c:"La DGT es órgano ejecutor.",d:"La JCT no es órgano consultivo."}},
{n:146,q:"La organización y funcionamiento del Consejo Superior de Tráfico y Seguridad de la Circulación Vial está regulado:",o:{a:"En el Real Decreto 317/2003, de 14 de marzo.",b:"En el Real Decreto 317/2013, de 23 de marzo.",c:"En el Real Decreto 517/2017, de 20 de noviembre.",d:"En el Real Decreto 213/2003, de 24 de abril."},correct:"b",why:{a:"⚠ Mi respuesta inicial (incorrecta): Correcto: RD 317/2003, de 14 de marzo.",b:"✓ Respuesta oficial. Año y fecha incorrectos.",c:"Norma distinta.",d:"Norma distinta."}},
{n:147,q:"El Consejo Superior de Tráfico, Seguridad Vial y Movilidad Sostenible está integrado por representantes de:",o:{a:"La Administración General del Estado, las Comunidades Autónomas, las ciudades de Ceuta y Melilla y las Administraciones Locales.",b:"Las fundaciones, las asociaciones de víctimas, el sector social de la discapacidad, las asociaciones de prevención de accidentes de tráfico y de fomento de la seguridad vial.",c:"Los centros de investigación y organizaciones profesionales, económicas y sociales más representativas directamente relacionadas con el tráfico, la seguridad vial y la movilidad sostenible.",d:"Todas las respuestas anteriores son correctas."},correct:"a",why:{a:"✓ Respuesta oficial. Parcial.",b:"Parcial.",c:"Parcial.",d:"⚠ Mi respuesta inicial (incorrecta): Los tres grupos forman parte del Consejo."}},
{n:148,q:"Según la Ley de Seguridad Vial (RDL 6/2015), el Consejo Superior de Tráfico, Seguridad Vial y Movilidad Sostenible:",o:{a:"Estará presidido por el Ministro del Interior.",b:"Funciona en Pleno, en Comisión Permanente, en Comisiones y en Grupos de Trabajo.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{a:"Parcial.",b:"Parcial.",c:"Ambas son ciertas (art.8 LSV).",d:"Las dos son ciertas."}},
{n:149,q:"Informar y, en su caso, proponer planes de actuación conjunta en materia de tráfico, seguridad vial o movilidad sostenible para el cumplimiento a las directrices del Gobierno o para someterlos a su aprobación, es una de las funciones de:",o:{a:"El Consejo Superior de Tráfico, Seguridad Vial y Movilidad Sostenible.",b:"La Dirección General de Tráfico.",c:"La Jefatura Central de Tráfico.",d:"Todas las respuestas anteriores son incorrectas."},correct:"a",why:{a:"Correcto: art.8 LSV — función del Consejo.",b:"La DGT ejecuta.",c:"La JCT (DGT) no propone planes así.",d:"La a es correcta."}},
{n:150,q:"Las propuestas de actuación del Consejo Superior de Tráfico, Seguridad Vial y Movilidad Sostenible:",o:{a:"No son vinculantes.",b:"Deben considerar, en particular, la viabilidad técnica de las medidas que incluyan.",c:"Deben considerar, en particular, la viabilidad financiera de las medidas que incluyan.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{a:"Parcial.",b:"Parcial.",c:"Parcial.",d:"Las tres se cumplen en las propuestas del Consejo."}},
{n:151,q:"Según la Ley de Seguridad Vial (RDL 6/2015), es función del Consejo Superior de Tráfico, Seguridad Vial y Movilidad Sostenible:",o:{a:"Asesorar a los órganos superiores y directivos del Ministerio del Interior en esta materia.",b:"La facultad de determinar la normativa técnica básica que afecte de manera directa a la seguridad vial.",c:"La previa homologación, en su caso, de los elementos de los vehículos, remolques y semirremolques que afecten a la seguridad vial.",d:"Son todas las citadas en las respuestas anteriores"},correct:"a",why:{a:"Correcto: el Consejo asesora.",b:"Es competencia AGE (art.4), no función del Consejo.",c:"Es competencia AGE (art.4).",d:"b y c no son funciones del Consejo."}},
{n:152,q:"Según la Ley de Seguridad Vial (RDL 6/2015), es función del Consejo Superior de Tráfico, Seguridad Vial y Movilidad Sostenible:",o:{a:"Informar los convenios o tratados internacionales sobre tráfico, seguridad vial o movilidad sostenible antes de la prestación del consentimiento del Estado para obligarse por ellos.",b:"Informar o proponer, en su caso, los proyectos de disposiciones generales que afecten al tráfico, la seguridad vial o la movilidad sostenible.",c:"Informar sobre la publicidad de los vehículos a motor.",d:"Son todas las citadas en las respuestas anteriores"},correct:"b",why:{a:"Parcial.",b:"✓ Respuesta oficial. Parcial.",c:"Parcial.",d:"⚠ Mi respuesta inicial (incorrecta): Las tres son funciones del Consejo (art.8 LSV)."}},
{n:153,q:"Impulsar, mediante las correspondientes propuestas, la actuación de los distintos organismos, entidades y asociaciones que desarrollen actividades en materia tráfico, seguridad vial o movilidad sostenible, es función de:",o:{a:"El Observatorio Nacional de Seguridad Vial.",b:"El Consejo Superior de Tráfico, Seguridad Vial y Movilidad Sostenible.",c:"El Ministerio del Interior.",d:"La Dirección General de tráfico."},correct:"b",why:{a:"El Observatorio no es ese órgano.",b:"Correcto: función del Consejo (art.8 LSV).",c:"El MI tiene otras funciones.",d:"La DGT ejecuta, no impulsa así."}},
{n:154,q:"Según la Ley de Seguridad Vial (RDL 6/2015), es función del Consejo Superior de Tráfico, Seguridad Vial y Movilidad Sostenible:",o:{a:"El registro de profesionales de la enseñanza de la conducción y de centros de formación de conductores.",b:"Conocer e informar sobre la evolución de la siniestralidad vial en España.",c:"Las respuestas a y b son correctas.",d:"Las respuestas ay b son incorrectas."},correct:"b",why:{a:"Es competencia del MI (art.5), no del Consejo.",b:"Correcto: función del Consejo (art.8 LSV).",c:"La a no es del Consejo.",d:"La b sí es función."}},
{n:155,q:"Según la Ley de Seguridad Vial (RDL 6/2015), es función del Consejo Superior de Tráfico, Seguridad Vial y Movilidad Sostenible:",o:{a:"Conocer del seguimiento y evaluaciones de las acciones en materia de seguridad vial puestas en marcha.",b:"La aprobación de reglamentos relacionados con la seguridad vial que no estén encomendados al Ministerio del Interior.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"d",why:{a:"⚠ Mi respuesta inicial (incorrecta): Correcto: función del Consejo (art.8 LSV).",b:"La aprobación de reglamentos no es del Consejo.",c:"La b no es del Consejo.",d:"✓ Respuesta oficial. La a sí lo es."}},
{n:156,q:"Según la Ley de Seguridad Vial (RDL 6/2015), es función del Consejo Superior de Tráfico, Seguridad Vial y Movilidad Sostenible:",o:{a:"Proponer a los Ayuntamientos medidas y actuaciones en materia de seguridad vial.",b:"Elaborar la estadística de accidentes de tráfico.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"a",why:{a:"Correcto: función del Consejo (art.8 LSV).",b:"La estadística la elabora/coordina el MI (DGT), no el Consejo.",c:"La b no es del Consejo.",d:"La a sí lo es."}},
{n:157,q:"Respecto al Consejo Superior de Tráfico, Seguridad Vial y Movilidad Sostenible, indique la afirmación incorrecta:",o:{a:"La composición, organización y funcionamiento del Consejo serán establecidos por el Ministerio del Interior.",b:"En las comunidades autónomas que no hayan recibido el traspaso de funciones y servicios en materia de tráfico y circulación de vehículos a motor, y en las ciudades de Ceuta y Melilla existe una Comisión del Consejo.",c:"Una Comisión del Consejo funciona para el estudio del tráfico, la seguridad vial y la movilidad sostenible en las vías urbanas.",d:"Las comunidades autónomas que hayan recibido el traspaso de funciones y servicios en materia de tráfico y circulación de vehículos a motor pueden establecer sus propios Consejos Autonómicos de Tráfico, Seguridad Vial y Movilidad Sostenible."},correct:"b",why:{a:"⚠ Mi respuesta inicial (incorrecta): La composición se determina reglamentariamente (vía Gobierno), no por sola decisión del Ministerio del Interior.",b:"✓ Respuesta oficial. Cierto.",c:"Cierto.",d:"Cierto."}},
{n:158,q:"Respecto al Consejo Superior de Tráfico, Seguridad Vial y Movilidad Sostenible, indique la afirmación incorrecta:",o:{a:"Al Ministro del Interior le corresponde su presidencia.",b:"Cualquier Comunidad Autónoma puede establecer su propio Consejo Autonómico de Seguridad Vial.",c:"La composición, organización y funcionamiento del Consejo se determinarán reglamentariamente.",d:"Podrán crearse Consejos Territoriales de Seguridad Vial."},correct:"b",why:{a:"Cierto.",b:"Solo las CCAA con traspaso de funciones de tráfico pueden hacerlo.",c:"Cierto.",d:"Cierto."}},
{n:159,q:"Según el art.9 de la Ley de Seguridad Vial (RDL 6/2015), se crea la Conferencia Sectorial de Tráfico, Seguridad Vial y Movilidad Sostenible, como órgano de cooperación entre la Administración General del Estado y las administraciones de:",o:{a:"Las Comunidades Autónomas que hayan asumido en sus Estatutos competencias para la protección de personas y bienes y el mantenimiento del orden público.",b:"Las Comunidades Autónomas que hayan recibido el traspaso de funciones y servicios en materia de tráfico y circulación de vehículos a motor.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"d",why:{a:"Parcial.",b:"Parcial.",c:"⚠ Mi respuesta inicial (incorrecta): Ambas son ciertas (art.9 LSV).",d:"✓ Respuesta oficial. Las dos son ciertas."}},
{n:160,q:"Según el art.9 de la Ley de Seguridad Vial (RDL 6/2015), la Conferencia Sectorial de Tráfico, Seguridad Vial y Movilidad Sostenible:",o:{a:"Desarrollará una actuación coordinada en esta materia, con atención a los principios de lealtad institucional y respeto recíproco en el ejercicio de las competencias atribuidas a dichas administraciones.",b:"Aprobará su reglamento interno, que regulará su organización y funcionamiento.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"d",why:{a:"Parcial.",b:"Parcial.",c:"⚠ Mi respuesta inicial (incorrecta): Ambas son ciertas (art.9 LSV).",d:"✓ Respuesta oficial. Las dos son ciertas."}},
{n:161,q:"El Reglamento General de Circulación fue aprobado por el Real Decreto 1428/2003 de 21 noviembre y desarrolla:",o:{a:"El artículo 5 y los Títulos I y II de la Ley de Seguridad Vial (RDL 6/2015).",b:"El artículo 2 y los Títulos II y III de la Ley de Seguridad Vial (RDL 6/2015).",c:"Los Títulos I, II y III de la Ley de Seguridad Vial (RDL 6/2015).",d:"El artículo 5 y los Títulos III y IV de la Ley de Seguridad Vial (RDL 6/2015)."},correct:"b",why:{a:"⚠ Mi respuesta inicial (incorrecta): Correcto: el RGC desarrolla el art.5 y los Títulos I y II LSV.",b:"✓ Respuesta oficial. Año y referencias incorrectas.",c:"Referencias incorrectas.",d:"Referencias incorrectas."}},
{n:162,q:"El Reglamento General de Circulación (RD 1428/2003):",o:{a:"Contiene un Título Preliminar y cinco Títulos más.",b:"Contiene 173 artículos, cuatro Disposiciones Adicionales y cuatro Disposiciones Finales.",c:"Contiene cuatro Anexos.",d:"Contiene todo lo reflejado en las respuestas anteriores."},correct:"d",why:{a:"Parcial.",b:"Parcial.",c:"Parcial.",d:"Las tres son correctas: estructura del RGC."}},
{n:163,q:"El Título Preliminar del Reglamento General de Circulación (RD 1428/2003):",o:{a:"Está dedicado al ámbito de aplicación de las normas sobre tráfico, circulación de vehículos a motor y seguridad vial.",b:"Está dedicado a las normas generales de comportamiento en la circulación.",c:"Está dedicado a la circulación de vehículos.",d:"El Reglamento General de Circulación no tiene Título Preliminar."},correct:"a",why:{a:"Correcto: el Título Preliminar regula el ámbito de aplicación.",b:"Eso es el Título I.",c:"Eso es el Título II.",d:"Sí tiene Título Preliminar."}},
{n:164,q:"El Título I del Reglamento General de Circulación (RD 1428/2003):",o:{a:"Está dedicado al ámbito de aplicación de las normas sobre tráfico, circulación de vehículos a motor y seguridad vial.",b:"Está dedicado a las normas generales de comportamiento en la circulación.",c:"Está dedicado a la circulación de vehículos.",d:"Está dedicado a otras normas de circulación."},correct:"b",why:{a:"Eso es el Título Preliminar.",b:"Correcto: Título I — normas generales de comportamiento.",c:"Eso es el Título II.",d:"Eso es el Título III."}},
{n:165,q:"En el Reglamento General de Circulación (RD 1428/2003) \"Normas sobre bebidas alcohólicas\" es la denominación que recibe...",o:{a:"El capítulo IV de su Título I.",b:"El capítulo I de su Título II.",c:"El Título II.",d:"Ninguna de las respuestas anteriores es correcta."},correct:"a",why:{a:"Correcto: Cap.IV del Título I.",b:"No es Cap.I del Tit.II.",c:"No es un Título entero.",d:"La a es correcta."}},
{n:166,q:"En el Reglamento General de Circulación (RD 1428/2003) \"Normas generales de los conductores\" es la denominación que recibe...",o:{a:"El capítulo IV de su Título II.",b:"El capítulo III de su Título I.",c:"El Título III.",d:"Ninguna de las respuestas anteriores es correcta."},correct:"b",why:{a:"Es Cap.III del Tit.I.",b:"Correcto: Cap.III del Título I.",c:"No es un Título.",d:"La b es correcta."}},
{n:167,q:"En el Reglamento General de Circulación (RD 1428/2003) las normas sobre prioridad de paso se contienen en...",o:{a:"El capítulo V de su Título II.",b:"El capítulo III de su Título I.",c:"El capítulo II de su Título II.",d:"El capítulo III de su Título II."},correct:"d",why:{a:"⚠ Mi respuesta inicial (incorrecta): Correcto: Cap.V del Título II — De la prioridad de paso.",b:"Cap.III Tit.I son normas generales de conductores.",c:"Otro capítulo.",d:"✓ Respuesta oficial. Otro capítulo."}},
{n:168,q:"El Título II del Reglamento General de Circulación (RD 1428/2003):",o:{a:"Está dedicado a las normas generales de comportamiento en la circulación.",b:"Está dedicado a la circulación de vehículos.",c:"Está dedicado a otras normas de circulación.",d:"Está dedicado a la señalización."},correct:"b",why:{a:"Eso es el Título I.",b:"Correcto: Título II — De la circulación de vehículos.",c:"Eso es el Título III.",d:"Eso es el Título IV."}},
{n:169,q:"El Título III del Reglamento General de Circulación (RD 1428/2003) se denomina:",o:{a:"Otras normas de circulación.",b:"De la señalización.",c:"De la circulación de vehículos.",d:"Circulación de Animales."},correct:"a",why:{a:"Correcto: Título III — De otras normas de circulación.",b:"Eso es el Título IV.",c:"Eso es el Título II.",d:"No es título del RGC."}},
{n:170,q:"En el Reglamento General de Circulación (RD 1428/2003), las normas que regulan los adelantamientos están comprendidas en...",o:{a:"El capítulo II de su Título II.",b:"El capítulo III de su Título III.",c:"El capítulo VII de su Título II.",d:"El capítulo VIII de su Título II."},correct:"c",why:{a:"Otro capítulo.",b:"El Título III no regula adelantamientos.",c:"Correcto: Cap.VII del Título II — De los adelantamientos.",d:"Otro capítulo."}},
{n:171,q:"En el Reglamento General de Circulación (RD 1428/2003), las normas que regulan la utilización del alumbrado están en el Título II, dentro de su capítulo...",o:{a:"V.",b:"VIII.",c:"X.",d:"IX."},correct:"c",why:{a:"Cap.V es prioridad.",b:"Otro capítulo.",c:"Correcto: Cap.X del Título II — De la utilización del alumbrado.",d:"Otro capítulo."}},
{n:172,q:"El Título IV del Reglamento General de Circulación (RD 1428/2003):",o:{a:"Está dedicado a las advertencias a los conductores.",b:"Está dedicado al comportamiento en caso de emergencia.",c:"Está dedicado a la señalización.",d:"Está dedicado a las señales en los vehículos."},correct:"c",why:{a:"No es el contenido del Título IV.",b:"No es el contenido del Título IV.",c:"Correcto: Título IV — De la señalización.",d:"Las señales en los vehículos son una parte, pero el Título trata de la señalización en general."}},
{n:173,q:"El Título V del Reglamento General de Circulación (RD 1428/2003):",o:{a:"Está dedicado a otras normas de circulación.",b:"Está dedicado a la circulación de vehículos.",c:"Está dedicado a la señalización.",d:"Está dedicado a las señales en los vehículos."},correct:"d",why:{a:"Eso es el Título III.",b:"Eso es el Título II.",c:"Eso es el Título IV.",d:"Correcto: Título V — Sobre las señales en los vehículos / régimen sancionador, según texto consolidado."}},
{n:174,q:"En el Reglamento General de Circulación (RD 1428/2003) \"Puertas y apagado del motor\" es la denominación que recibe...",o:{a:"El capítulo IV de su Título III.",b:"El capítulo VIII de su Título II.",c:"El capítulo V de su Título IV.",d:"El capítulo I de su Título III."},correct:"b",why:{a:"Otro capítulo.",b:"Correcto: Cap.VIII del Título II.",c:"Es señalización.",d:"Otro capítulo."}},
{n:175,q:"En el Reglamento General de Circulación (RD 1428/2003) \"De los tipos y significados de las señales de circulación y marcas viales\" es la denominación que recibe...",o:{a:"El capítulo VI de su Título IV.",b:"El capítulo V de su Título III.",c:"El capítulo V de su Título IV.",d:"El capítulo VI de su Título V."},correct:"c",why:{a:"Otro capítulo.",b:"Tit.III no es señalización.",c:"Correcto: Cap.V del Título IV.",d:"Tit.V no es ese contenido."}},
{n:176,q:"En el Reglamento General de Circulación (RD 1428/2003) \"Retirada, sustitución y alteración de las señales\" es la denominación que recibe...",o:{a:"El capítulo IV de su Título III.",b:"El capítulo VIII de su Título II.",c:"El capítulo V de su Título IV.",d:"El capítulo I de su Título III."},correct:"c",why:{a:"Tit.III no es señalización.",b:"Tit.II no es señalización.",c:"Correcto: Cap.V del Título IV (señalización). Cabe verificar la numeración exacta en plantilla oficial.",d:"Tit.III no es señalización."}},
{n:177,q:"El Anexo I del Reglamento General de Circulación (RD 1428/2003) se denomina:",o:{a:"Normas y condiciones de circulación de los vehículos especiales y de los vehículos en régimen de transporte especial.",b:"Señales de Circulación.",c:"Pruebas deportivas, marchas ciclistas y otros eventos.",d:"Pictograma indicativo del uso obligatorio del cinturón de seguridad en los asientos de los vehículos destinados al transporte de personas de más de nueve plazas, incluido el conductor, en los que figure el mismo."},correct:"a",why:{a:"Correcto: Anexo I.",b:"Es Anexo II.",c:"Es Anexo III.",d:"Es Anexo IV."}},
{n:178,q:"El Anexo III del Reglamento General de Circulación (RD 1428/2003) se denomina:",o:{a:"Normas y condiciones de circulación de los vehículos especiales y de los vehículos en régimen de transporte especial.",b:"Señales de Circulación.",c:"Pruebas deportivas, marchas ciclistas y otros eventos.",d:"Pictograma indicativo del uso obligatorio del cinturón de seguridad en los asientos de los vehículos destinados al transporte de personas de más de nueve plazas, incluido el conductor, en los que figure el mismo."},correct:"c",why:{a:"Es Anexo I.",b:"Es Anexo II.",c:"Correcto: Anexo III.",d:"Es Anexo IV."}},
{n:179,q:"El Anexo II del Reglamento General de Circulación (RD 1428/2003) se denomina:",o:{a:"Normas y condiciones de circulación de los vehículos especiales y de los vehículos en régimen de transporte especial.",b:"Señales de Circulación.",c:"Pruebas deportivas, marchas ciclistas y otros eventos.",d:"Pictograma indicativo del uso obligatorio del cinturón de seguridad en los asientos de los vehículos destinados al transporte de personas de más de nueve plazas, incluido el conductor, en los que figure el mismo."},correct:"b",why:{a:"Es Anexo I.",b:"Correcto: Anexo II.",c:"Es Anexo III.",d:"Es Anexo IV."}},
{n:180,q:"El Anexo IV del Reglamento General de Circulación (RD 1428/2003) se denomina:",o:{a:"Normas y condiciones de circulación de los vehículos especiales y de los vehículos en régimen de transporte especial.",b:"Señales de Circulación.",c:"Pruebas deportivas, marchas ciclistas y otros eventos.",d:"Pictograma indicativo del uso obligatorio del cinturón de seguridad en los asientos de los vehículos destinados al transporte de personas de más de nueve plazas, incluido el conductor, en los que figure el mismo."},correct:"d",why:{a:"Es Anexo I.",b:"Es Anexo II.",c:"Es Anexo III.",d:"Correcto: Anexo IV."}},
{n:181,q:"Los preceptos del Reglamento General de Circulación (RD 1428/2003):",o:{a:"Serán aplicables en todo el territorio nacional.",b:"Obligarán a los titulares y usuarios de las vías y terrenos públicos aptos para la circulación, tanto urbanos como interurbanos.",c:"Obligarán a los usuarios de las vías y terrenos que, sin ser aptos para la circulación, sean de uso común y, en defecto de otras normas, a los de las vías y terrenos privados que sean utilizados por una colectividad indeterminada de usuarios.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{a:"Parcial.",b:"Parcial.",c:"Parcial.",d:"Las tres reflejan el ámbito del RGC (art.2)."}},
{n:182,q:"Respecto a los preceptos del Reglamento General de Circulación (RD 1428/2003), indique la respuesta incorrecta:",o:{a:"Se aplicarán a los animales sueltos y en rebaño y vehículos de cualquier clase que se encuentren incorporados al tráfico.",b:"Obligarán a los usuarios de las vías y terrenos que, sin ser aptos para la circulación, sean de uso común",c:"Se aplicarán a los caminos de dominio público, a las pistas y terrenos públicos aptos para la circulación y a todas las vías de uso común, públicas o privadas.",d:"Serán aplicables a los caminos, terrenos, garajes, cocheras y otros locales de similar naturaleza, constituidos dentro de fincas privadas y destinados al uso exclusivo de los propietarios y sus dependientes."},correct:"d",why:{a:"Correcto: el RGC se aplica a vehículos y animales en tráfico.",b:"Correcto: obliga en vías de uso común.",c:"Correcto.",d:"El RGC NO se aplica a espacios privados de uso exclusivo de sus propietarios."}},
{n:183,q:"El Título I del Reglamento General de Circulación (RD 1428/2003) está dedicado a las normas generales de comportamiento en la circulación y está estructurado:",o:{a:"En cuatro capítulos, que abarcan los artículos 3 a 38.",b:"En cinco capítulos, que abarcan los artículos 2 a 28.",c:"En tres capítulos, que abarcan los artículos 12 a 28.",d:"En dos capítulos y tres secciones, que abarcan los artículos 2 a 38."},correct:"a",why:{a:"Correcto: estructura del Título I del RGC.",b:"Numeración incorrecta.",c:"Numeración incorrecta.",d:"Estructura incorrecta."}},
{n:184,q:"El Capítulo I del Título I del Reglamento General de Circulación (RD 1428/2003) se denomina:",o:{a:"Normas Generales.",b:"De la carga de vehículos y del transporte de personas y mercancías o cosas.",c:"Normas generales de los conductores.",d:"Normas sobre estupefacientes, psicotrópicos, estimulantes u otras sustancias análoga"},correct:"a",why:{a:"Correcto: Cap.I — Normas Generales.",b:"Es Cap.II.",c:"Es Cap.III.",d:"Es Cap.V."}},
{n:185,q:"Respecto a las normas generales establecidas en el Capítulo I del Título I del Reglamento General de Circulación (RD 1428/2003), indique cual de las siguientes es incorrecta:",o:{a:"Los usuarios de la vía están obligados a comportarse de forma que no entorpezcan indebidamente la circulación ni causen peligro, perjuicios o molestias innecesarias a las personas, o daños a los bienes.",b:"Las conductas referidas a la conducción negligente tendrán la consideración de infracciones muy graves y las referidas a la conducción temeraria tendrán la consideración de infracciones graves.",c:"Se deberá conducir con la diligencia y precaución necesarias para evitar todo daño, propio o ajeno, cuidando de no poner en peligro, tanto al mismo conductor como a los demás ocupantes del vehículo y al resto de los usuarios de la vía.",d:"Queda terminantemente prohibido conducir de modo negligente o temerario."},correct:"b",why:{a:"Correcto.",b:"Es al revés: la conducción negligente es infracción grave y la temeraria es muy grave.",c:"Correcto.",d:"Correcto."}},
{n:186,q:"Según lo previsto en el Capítulo I del Título I del Reglamento General de Circulación (RD 1428/2003), las conductas referidas a la conducción negligente tendrán la consideración de:",o:{a:"Infracciones graves.",b:"Infracciones muy graves.",c:"Delito menos grave.",d:"Delito grave."},correct:"a",why:{a:"Correcto: conducción negligente — infracción grave.",b:"La conducción temeraria es muy grave.",c:"No es delito.",d:"No es delito."}},
{n:187,q:"Según lo previsto en el Capítulo I del Título I del Reglamento General de Circulación (RD 1428/2003), las conductas referidas a la conducción temeraria tendrán la consideración de:",o:{a:"Infracciones graves.",b:"Infracciones muy graves.",c:"Delito menos grave.",d:"Delito grave."},correct:"b",why:{a:"La negligente es grave.",b:"Correcto: conducción temeraria — infracción muy grave.",c:"No es delito.",d:"No es delito."}},
{n:188,q:"Respecto a las actividades que afectan a la seguridad de la circulación, en el Capítulo I del Título I del Reglamento General de Circulación (RD 1428/2003) se establece que:",o:{a:"La realización de obras, instalaciones, colocación de contenedores, mobiliario urbano o cualquier otro elemento u objeto de forma permanente o provisional en las vías o terrenos objeto de aplicación de la legislación sobre tráfico, circulación de vehículos a motor y seguridad vial necesitará la autorización previa de su titular y se regirán por lo dispuesto en la legislación de carreteras y en sus reglamentos de desarrollo, y en las normas municipales.",b:"Se prohíbe arrojar, depositar o abandonar sobre la vía objetos o materias que puedan entorpecer la libre circulación, parada o estacionamiento, hacerlos peligrosos o deteriorar aquélla o sus instalaciones, o producir en ella o en sus inmediaciones efectos que modifiquen las condiciones apropiadas para circular, parar o estacionar.",c:"No se instalará en vías o terrenos objeto del ámbito de aplicación de la legislación sobre tráfico, circulación de vehículos a motor y seguridad vial ningún aparato, instalación o construcción, ni se realizarán actuaciones como rodajes, encuestas o ensayos, aunque sea con carácter provisional o temporal, que pueda entorpecer la circulación.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{a:"Parcial.",b:"Parcial.",c:"Parcial.",d:"Las tres son ciertas (art.4 RGC)."}},
{n:189,q:"De conformidad con lo dispuesto en el Reglamento General de Circulación (RD 1428/2003), indique cuál de la siguientes actividades necesita autorización previa del titular de la vía:",o:{a:"La colocación de un contenedor.",b:"La colocación de mobiliario urbano.",c:"La realización de obras.",d:"Todas las citadas en las respuestas anteriores necesitan dicha autorización."},correct:"d",why:{a:"Parcial.",b:"Parcial.",c:"Parcial.",d:"Las tres requieren autorización previa del titular."}},
{n:190,q:"De conformidad con lo dispuesto en el Reglamento General de Circulación (RD 1428/2003), indique la afirmación incorrecta:",o:{a:"En ningún caso se considerarán obstáculos en la calzada los resaltos en los pasos para peatones ni las bandas transversales.",b:"Tanto en vías urbanas como interurbanas se prohíbe la circulación de ciclomotores sin el preceptivo dispositivo silenciador de las explosiones.",c:"Se prohíbe la circulación de los vehículos de motor de combustión interna que no se hallen dotados de un dispositivo que evite la proyección descendente al exterior del combustible no quemado.",d:"Los agentes de la autoridad podrán inmovilizar el vehículo cuando supere los niveles de ruido permitidos reglamentariamente."},correct:"a",why:{a:"No es «en ningún caso»: solo no se considerarán obstáculos si cumplen la regulación básica y garantizan la seguridad vial.",b:"Correcto.",c:"Correcto.",d:"Correcto."}},
{n:191,q:"De conformidad con lo dispuesto en el Reglamento General de Circulación (RD 1428/2003), quienes hubieran creado sobre la vía algún obstáculo o peligro:",o:{a:"Deberán hacerlo desaparecer lo antes posible.",b:"Adoptarán las medidas necesarias para que pueda ser advertido por los demás usuarios y para que no se dificulte la circulación.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{a:"Parcial.",b:"Parcial.",c:"Ambas son obligaciones del causante.",d:"Las dos son ciertas."}},
{n:192,q:"Según las normas generales establecidas en el Capítulo I del Título I del Reglamento General de Circulación (RD 1428/2003), no se considerarán obstáculos en la calzada los resaltos en los pasos para peatones y bandas transversales:",o:{a:"Siempre que cumplan la regulación básica establecida al efecto por el Ministerio de Fomento.",b:"Siempre que se garantice la seguridad vial de los usuarios y, en particular, de los ciclistas.",c:"Siempre que se cumpla lo descrito en las respuestas a y b.",d:"Todas las respuestas anteriores son incorrectas."},correct:"c",why:{a:"Parcial.",b:"Parcial.",c:"Ambas condiciones deben cumplirse simultáneamente.",d:"Las dos son ciertas."}},
{n:193,q:"Para advertir la presencia en la vía de cualquier obstáculo o peligro creado, el causante de éste deberá señalizarlo de forma eficaz, tanto de día como de noche, de conformidad con lo dispuesto:",o:{a:"En los artículos 130.3, 140 y 173 de la Ley de Seguridad Vial.",b:"En los artículos 130.3, 140 y 173 del Reglamento General de Circulación.",c:"En los artículos 13, 14 y 17 de la Ley de Seguridad Vial.",d:"En los artículos 13, 14 y 17 del Reglamento General de Circulación."},correct:"b",why:{a:"La LSV no tiene esos artículos.",b:"Correcto: arts. 130.3, 140 y 173 del RGC.",c:"No corresponde.",d:"No corresponde a esos artículos."}},
{n:194,q:"Deberán regirse por los principios de utilización de los recursos idóneos y estrictamente necesarios en cada caso, todas las actuaciones que deban desarrollar los servicios:",o:{a:"De asistencia mecánica.",b:"De asistencia sanitaria o cualquier otro tipo de intervención.",c:"Las respuestas a y b son incorrectas.",d:"Las respuestas a y b son correctas."},correct:"d",why:{a:"Parcial.",b:"Parcial.",c:"Ambas son ciertas.",d:"Correcto: ambos servicios deben regirse por esos principios."}},
{n:195,q:"Respecto a la señalización de obstáculos y peligros, el Reglamento General de Circulación (RD 1428/2003) establece que el organismo autónomo Jefatura Central de Tráfico o, en su caso, la autoridad autonómica o local responsable de la regulación del tráfico, o sus agentes:",o:{a:"Acordarán la presencia y permanencia en la zona de intervención de todo el personal y equipo que sea imprescindible.",b:"Garantizará la ausencia de personas ajenas a las labores propias de la asistencia de que se trate.",c:"Será la encargada de señalar en cada caso concreto los lugares donde deben situarse los vehículos de servicios de urgencia o de otros servicios especiales, atendiendo a la prestación de la mejor asistencia y velando por el mejor auxilio de las personas.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{a:"Parcial.",b:"Parcial.",c:"Parcial.",d:"Las tres son funciones previstas."}},
{n:196,q:"Respecto a la señalización de obstáculos y peligros regulada en el Capítulo I del Título I del Reglamento General de Circulación (RD 1428/2003), indique la afirmación incorrecta:",o:{a:"El comportamiento de los conductores y usuarios en caso de emergencia se ajustará a lo establecido en los artículos 69, 129 y 130 y, en particular, el de los conductores de los vehículos de servicio de urgencia, a lo dispuesto en los artículos 67, 68, 111 y 112.",b:"La actuación de los servicios de urgencias seguirá en todo momento las instrucciones que imparta la Jefatura Provincial de Tráfico o, en su defecto, las que impartan los responsables de los encargados de la vigilancia del tráfico.",c:"La detención, parada o estacionamiento a los vehículos destinados a los servicios citados deberá efectuarse de forma que no cree un nuevo peligro, y donde cause menor obstáculo a la circulación.",d:"Los supuestos de parada o estacionamiento en lugares distintos de los fijados por los agentes de la autoridad responsable del tráfico tendrán la consideración de infracción grave."},correct:"b",why:{a:"Correcto.",b:"Las instrucciones las imparte la Jefatura Central de Tráfico (DGT), no la Provincial.",c:"Correcto.",d:"Correcto."}},
{n:197,q:"Según lo previsto en el Reglamento General de Circulación (RD 1428/2003), la actuación de los equipos de los servicios de urgencia, así como la de los de asistencia mecánica y de conservación de carreteras:",o:{a:"Deberá procurar en todo momento la menor afectación posible sobre el resto de la circulación, ocupando el mínimo posible de la calzada.",b:"Seguirá en todo momento las instrucciones que imparta la Jefatura Provincial de Tráfico o, en su defecto, las que impartan los responsables de los encargados de la vigilancia del tráfico.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"a",why:{a:"Correcto: deben minimizar la afectación.",b:"La autoridad referida en la ley es la JCT, no la Provincial.",c:"La b es inexacta.",d:"La a sí es cierta."}},
{n:198,q:"Según lo previsto en el Reglamento General de Circulación (RD 1428/2003), los equipos de los servicios de urgencia y los de asistencia mecánica y de conservación de carreteras, seguirán en todo momento las instrucciones que imparta:",o:{a:"El Ministerio del Interior.",b:"El organismo autónomo Jefatura Central de Tráfico o, en su caso, la autoridad autonómica o local responsable de la regulación del tráfico, o sus agentes.",c:"La Jefatura Provincial de Tráfico competente en el territorio de que se trate.",d:"Todas las respuestas anteriores son incorrectas."},correct:"b",why:{a:"No directamente el MI.",b:"Correcto: la JCT o autoridad autonómica/local responsable.",c:"No es la Provincial.",d:"La b es correcta."}},
{n:199,q:"Respecto a la prevención de incendios, en el art.6 del Reglamento General de Circulación (RD 1428/2003):",o:{a:"Se prohíben los vertederos de basuras y residuos dentro de la zona de afección de las carreteras, salvo los autorizados previamente por el Ministerio competente en materia medioambiental.",b:"Se prohíbe arrojar a la vía o en sus inmediaciones cualquier objeto que pueda dar lugar a la producción de incendios o, en general, poner en peligro la seguridad vial.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"b",why:{a:"Parcial.",b:"✓ Respuesta oficial. Parcial.",c:"⚠ Mi respuesta inicial (incorrecta): Ambas son prohibiciones del art.6 RGC.",d:"Las dos son ciertas."}},
{n:200,q:"Las infracciones a lo preceptuado en el art.6 del Reglamento General de Circulación (RD 1428/2003), sobre prevención de incendios, tendrán la consideración de:",o:{a:"Infracción grave.",b:"Infracción muy grave.",c:"Delito grave.",d:"Delito menos grave."},correct:"a",why:{a:"Correcto: infracción grave.",b:"No es muy grave.",c:"No es delito.",d:"No es delito."}},
{n:201,q:"Respecto a la emisión de perturbaciones y contaminantes, el art.7 del Reglamento General de Circulación (RD 1428/2003), establece que:",o:{a:"Los vehículos no podrán circular por las vías o terrenos objeto de la legislación sobre tráfico, circulación de vehículos a motor y seguridad vial si emiten perturbaciones electromagnéticas, con niveles de emisión de ruido superiores a los límites establecidos por las normas específicamente reguladoras de la materia.",b:"Los vehículos no podrán emitir gases o humos en valores superiores a los límites establecidos ni en los supuestos de haber sido objeto de una reforma de importancia no autorizada.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{a:"Parcial.",b:"Parcial.",c:"Ambas son ciertas (art.7 RGC).",d:"Las dos son ciertas."}},
{n:202,q:"Respecto a la emisión de perturbaciones y contaminantes, regulada en el art.7 del Reglamento General de Circulación (RD 1428/2003), indique cual de las siguientes afirmaciones es incorrecta:",o:{a:"Todos los conductores de vehículos quedan obligados a colaborar en las pruebas de detección que permitan comprobar las posibles deficiencias.",b:"Los vehículos podrán emitir gases o humos en valores superiores a los límites establecidos, siempre y cuando hayan sido objeto de una reforma de importancia autorizada.",c:"Tanto en las vías públicas urbanas como en las interurbanas se prohíbe la circulación de vehículos a motor y ciclomotores con el llamado escape libre, sin el preceptivo dispositivo silenciador de las explosiones.",d:"Los agentes de la autoridad podrán inmovilizar el vehículo en el caso de que supere los niveles de gases, humos y ruidos permitidos reglamentariamente, según el tipo de vehículo."},correct:"b",why:{a:"Correcto.",b:"Aunque la reforma esté autorizada, no se pueden superar los límites de emisión.",c:"Correcto.",d:"Correcto."}},
{n:203,q:"El art.7 del Reglamento General de Circulación (RD 1428/2003), prohíbe la circulación de vehículos a motor y ciclomotores cuando los gases expulsados por los motores, en lugar de atravesar un silenciador eficaz, salgan desde el motor:",o:{a:"A través de uno incompleto.",b:"A través de uno inadecuado o deteriorado.",c:"A través de tubos resonadores.",d:"A través de cualquiera de los citados en las respuestas anteriores."},correct:"d",why:{a:"Parcial.",b:"Parcial.",c:"Parcial.",d:"Los tres supuestos están prohibidos."}},
{n:204,q:"El art.7 del Reglamento General de Circulación (RD 1428/2003), prohíbe la circulación de vehículos de motor de combustión interna:",o:{a:"Que circulen sin hallarse dotados de un dispositivo que evite la proyección descendente al exterior de combustible no quemado.",b:"Que lancen humos que puedan dificultar la visibilidad a los conductores de otros vehículos o resulten nocivos.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{a:"Parcial.",b:"Parcial.",c:"Ambas situaciones están prohibidas.",d:"Las dos son ciertas."}},
{n:205,q:"El art.7 del Reglamento General de Circulación (RD 1428/2003), prohíbe:",o:{a:"La emisión de los contaminantes a que se refiere el apartado 1 de dicho artículo (ruidos, gases y humos) producida por vehículos a motor por encima de las limitaciones previstas en las normas reguladoras de los vehículos.",b:"La emisión de los contaminantes a que se refiere el apartado 1 de dicho artículo (ruidos, gases y humos) por otros focos emisores de contaminantes distintos de los producidos por vehículos a motor, cualquiera que fuese su naturaleza, por encima de los niveles que el Gobierno establezca con carácter general.",c:"En concreto, los vertederos de basuras y residuos dentro de la zona de afección de las carreteras, en todo caso, y fuera de ella cuando exista peligro de que el humo producido por la incineración de las basuras o incendios ocasionales pueda alcanzar la carretera.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{a:"Parcial.",b:"Parcial.",c:"Parcial.",d:"Las tres están prohibidas."}},
{n:206,q:"El Capítulo II del Título I del Reglamento General de Circulación (RD 1428/2003) se denomina:",o:{a:"Normas Generales.",b:"De la carga de vehículos y del transporte de personas y mercancías o cosas.",c:"Normas generales de los conductores.",d:"Normas sobre estupefacientes, psicotrópicos, estimulantes u otras sustancias análoga"},correct:"b",why:{a:"Es Cap.I.",b:"Correcto: Cap.II — De la carga y del transporte.",c:"Es Cap.III.",d:"Es Cap.V."}},
{n:207,q:"En el art.8 del Reglamento General de Circulación (RD 1428/2003) se prohíbe cargar los vehículos o transportar en ellos personas, mercancías o cosas:",o:{a:"De forma distinta a la que se determina en el Capítulo II del Título I de este Reglamento.",b:"Que puedan suponer riesgo para la seguridad vial, por sus dimensiones o por el número de personas.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"a",why:{a:"✓ Respuesta oficial. Parcial.",b:"Parcial.",c:"⚠ Mi respuesta inicial (incorrecta): Ambas prohibiciones están en el art.8 RGC.",d:"Las dos son ciertas."}},
{n:208,q:"Según el Reglamento General de Circulación (RD 1428/2003), el número de personas transportadas en un vehículo:",o:{a:"No podrá ser superior al de plazas autorizadas para el mismo.",b:"Puede sobrepasarse hasta en un 10% cuando se transporten simultáneamente pasajeros y sus equipajes, siempre que la suma de ambas cargas no exceda de la MMA para el vehículo.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"a",why:{a:"Correcto: no puede superarse el número de plazas autorizadas.",b:"No existe ese margen del 10%.",c:"La b es falsa.",d:"La a es cierta."}},
{n:209,q:"La previsión del Reglamento General de Circulación (RD 1428/2003) que obliga a indicar el número de plazas autorizadas, mediante la colocación de placas en el interior del vehículo, solo es aplicable:",o:{a:"A los vehículos de servicio público que realicen transportes interurbanos.",b:"A los vehículos de servicio público y a los autobuses.",c:"A los vehículos destinados al transporte de personas y vehículos mixtos.",d:"Todas las respuestas anteriores son incorrectas."},correct:"b",why:{a:"No solo interurbanos.",b:"Correcto: art.9 RGC — vehículos de servicio público y autobuses.",c:"No es la formulación legal.",d:"La b es correcta."}},
{n:210,q:"El art.9.1 del Reglamento General de Circulación (RD 1428/2003) obliga a indicar el número de plazas autorizadas, mediante la colocación de placas en su interior, a los vehículos de servicio público y autobuses:",o:{a:"Correcto, sin que, en ningún caso, pueda sobrepasarse, entre viajeros y equipaje, la masa máxima autorizada para el vehículo.",b:"Incorrecto.",c:"Correcto, sin que pueda sobrepasarse la masa máxima del vehículo entre viajeros y equipaje.",d:"Correcto, así como a los de servicios privados cuando transporten menores."},correct:"a",why:{a:"Correcto: la suma no puede superar la MMA.",b:"Sí es correcto.",c:"Falta la coletilla «en ningún caso».",d:"No incluye los servicios privados."}},
{n:211,q:"El Reglamento General de Circulación (RD 1428/2003) determina que para computar el número de plazas en los vehículos dedicados al transporte escolar y de menores:",o:{a:"Se estará a lo dispuesto en el Anexo III del Reglamento General de Circulación.",b:"Se estará a lo dispuesto en la Ley de Ordenación de los Transportes Terrestres.",c:"Se estará a lo dispuesto en la normativa específica sobre la materia.",d:"Ninguna de las respuestas anteriores es correcta."},correct:"c",why:{a:"Anexo III no regula esto.",b:"La LOTT no detalla esto.",c:"Correcto: normativa específica de transporte escolar y de menores.",d:"La c es correcta."}},
{n:212,q:"La previsión del Reglamento General de Circulación (RD 1428/2003) que considera infracción de carácter muy grave la ocupación excesiva del vehículo que suponga aumentar en un 50% el número de plazas autorizadas, excluido el conductor, no es aplicable...",o:{a:"A los autobuses de líneas urbanas.",b:"A los autobuses de líneas interurbanas.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{a:"⚠ Mi respuesta inicial (incorrecta): Correcto: la previsión no se aplica a los autobuses urbanos.",b:"Sí se aplica a interurbanos.",c:"✓ Respuesta oficial. La b es falsa.",d:"La a es cierta."}},
{n:213,q:"La ocupación excesiva de un vehículo que suponga aumentar en un 50% el número de plazas autorizadas, excluida la del conductor:",o:{a:"Tendrá la consideración de infracción muy graves (artículo 76 u. del RDL 6/2015).",b:"Implicará la inmovilización del vehículo por los agentes de la autoridad, que lo mantendrán inmovilizado mientras subsista la causa de la infracción (artículo 104.1. g. del RDL 6/2015).",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{a:"Parcial.",b:"Parcial.",c:"Ambas son consecuencias previstas.",d:"Las dos son ciertas."}},
{n:214,q:"De acuerdo con lo dispuesto en el Reglamento General de Circulación (RD 1428/2003), indique cuál de las afirmaciones siguientes es incorrecta:",o:{a:"Está prohibido transportar personas en emplazamiento distinto al destinado y acondicionado para ellas en los vehículos.",b:"En los vehículos de transporte de mercancías podrán viajar personas en el lugar reservado a la carga, en las condiciones que se establezcan en las disposiciones que regulan la materia.",c:"En los transportes colectivos de personas, el conductor, y en su caso, el encargado deben velar por la seguridad de los viajeros en las subidas y bajadas.",d:"En los transportes colectivos de personas, el conductor, y en su caso, el encargado deben solicitar la intervención de los Cuerpos de Seguridad para expulsar de los vehículos a los viajeros que incumplan las normas."},correct:"d",why:{a:"Correcto.",b:"Correcto.",c:"Correcto.",d:"El conductor o encargado puede prohibir la entrada y ordenar la salida directamente; no es necesaria la intervención de los Cuerpos de Seguridad."}},
{n:215,q:"De acuerdo con lo dispuesto en el Reglamento General de Circulación (RD 1428/2003), indique cuál de las afirmaciones siguientes es incorrecta:",o:{a:"En los vehículos de transporte de mercancías o cosas podrán viajar personas en el lugar reservado a la carga, en las condiciones que se establecen en las disposiciones que regulan la materia.",b:"Los vehículos autorizados a transportar simultáneamente personas y carga deberán estar provistos de una protección adecuada a la carga que transporten, de manera que no estorbe a los ocupantes ni pueda dañarlos en caso de ser proyectada.",c:"La protección adecuada que deben llevar los vehículos autorizados a transportar simultáneamente personas y carga, se ajustará a lo previsto en la legislación reguladora de los vehículos.",d:"En los vehículos autorizados a transportar simultáneamente personas y carga, no llevar instalada la protección adecuada a la carga que transporten, constituye infracción de carácter grave (art. 77 ll) del RDL 6/2015)."},correct:"d",why:{a:"Correcto.",b:"Correcto.",c:"Correcto.",d:"La infracción es muy grave, no grave."}},
{n:216,q:"En los vehículos autorizados a transportar simultáneamente personas y carga, no llevar instalada la protección adecuada a la carga que transporten, constituye:",o:{a:"Infracción de carácter muy grave.",b:"Infracción de carácter grave.",c:"Infracción de carácter leve.",d:"Delito Leve."},correct:"b",why:{a:"⚠ Mi respuesta inicial (incorrecta): Correcto: infracción muy grave.",b:"✓ Respuesta oficial. No es grave.",c:"No es leve.",d:"No es delito."}},
{n:217,q:"Respecto al Transporte colectivo de personas, el Capítulo II del Título I del Reglamento General de Circulación (RD 1428/2003), dispone que:",o:{a:"El conductor deberá efectuar las paradas y arrancadas sin sacudidas ni movimientos bruscos.",b:"El conductor deberá efectuar las paradas lo más cerca posible del borde derecho de la calzada y se abstendrá de realizar acto alguno que le pueda distraer durante la marcha.",c:"El conductor y, en su caso, el encargado, tanto durante la marcha como en las subidas y bajadas, velarán por la seguridad de los viajeros.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{a:"Parcial.",b:"Parcial.",c:"Parcial.",d:"Las tres son obligaciones del conductor."}},
{n:218,q:"Según lo previsto en el Reglamento General de Circulación (RD 1428/2003), en los vehículos destinados al servicio público de transporte colectivo de personas se prohíbe a los viajeros:",o:{a:"Distraer al conductor durante la marcha del vehículo.",b:"Entrar o salir del vehículo por lugares distintos a los destinados, respectivamente, a estos fines.",c:"Entrar en el vehículo cuando se haya hecho la advertencia de que está completo.",d:"Se prohíbe todo lo descrito en las respuestas anteriores."},correct:"d",why:{a:"Parcial.",b:"Parcial.",c:"Parcial.",d:"Las tres conductas están prohibidas (art.11 RGC)."}},
{n:219,q:"De las prohibiciones a los viajeros, reguladas en el art.11 del Reglamento General de Circulación (RD 1428/2003), indique cual de las siguientes es incorrecta:",o:{a:"Dificultar innecesariamente el paso en los lugares destinados al tránsito de personas.",b:"Llevar consigo cualquier animal, exceptuando de esta prohibición, siempre bajo su responsabilidad, a los invidentes acompañados de perros, especialmente adiestrados como lazarillos.",c:"Llevar materias u objetos peligrosos en condiciones distintas de las establecidas en la regulación específica sobre la materia.",d:"Desatender las instrucciones que, sobre el servicio, den el conductor o el encargado del vehículo."},correct:"b",why:{a:"⚠ Mi respuesta inicial (incorrecta): No es una prohibición a los viajeros del art.11 RGC.",b:"✓ Respuesta oficial. Sí lo es.",c:"Sí lo es.",d:"Sí lo es."}},
{n:220,q:"Respecto de las prohibiciones a los viajeros, el art.11 del Reglamento General de Circulación (RD 1428/2003), dispone:",o:{a:"La prohibición de llevar consigo cualquier animal, salvo que exista en el vehículo lugar destinado para su transporte. Se exceptúan de esta prohibición, siempre bajo su responsabilidad, a los invidentes acompañados de perros, especialmente adiestrados como lazarillos.",b:"Que el conductor y, en su caso, el encargado de los vehículos destinados al servicio público de transporte colectivo de personas deben prohibir la entrada y ordenar su salida a los viajeros que incumplan los preceptos establecidos en este apartado.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{a:"Parcial.",b:"Parcial.",c:"Ambas previsiones figuran en el art.11.",d:"Las dos son ciertas."}},
{n:221,q:"Según el art.12 del Reglamento General de Circulación (RD 1428/2003), los ciclos que, por construcción, no puedan ser ocupados por más de una persona podrán transportar, no obstante, cuando el conductor sea mayor de edad:",o:{a:"Un menor de hasta siete años, en asiento adicional que habrá de ser homologado.",b:"Un menor de hasta siete años, en asiento adicional adaptado.",c:"Un menor de hasta ocho años, en asiento adicional adaptado.",d:"Un menor de hasta nueve años, en asiento adicional homologado."},correct:"a",why:{a:"Correcto: hasta 7 años, en asiento adicional homologado.",b:"El asiento debe ser homologado, no solo adaptado.",c:"La edad es hasta 7 años.",d:"La edad es hasta 7 años."}},
{n:222,q:"El art.12 del Reglamento General de Circulación (RD 1428/2003) determina que en los ciclomotores y motocicletas podrá viajar un ocupante, siempre que así conste en su licencia o permiso de circulación, el pasajero sea mayor de 12 años, utilice casco de protección y..",o:{a:"Viaje a horcajadas con los pies apoyados en los reposapiés laterales.",b:"Utilice el asiento correspondiente detrás del conductor.",c:"En ningún caso podrá situarse el pasajero en lugar intermedio entre la persona que conduce y el manillar de dirección del ciclomotor o motocicleta.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{a:"Parcial.",b:"Parcial.",c:"Parcial.",d:"Las tres condiciones se cumplen."}},
{n:223,q:"En el artículo 12 del Reglamento General de Circulación (RD 1428/2003) se determina que, como excepción, el ocupante de un ciclomotor o motocicleta podrá ser una persona mayor de 7 años, en cuyo caso se exige como requisito que el conductor sea...",o:{a:"Su padre, madre o tutor.",b:"Cualquier persona mayor de edad autorizada por su padre, madre o tutor",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{a:"Parcial.",b:"Parcial.",c:"Ambos casos están admitidos.",d:"Las dos son ciertas."}},
{n:224,q:"Según el Reglamento General de Circulación (RD 1428/2003), podrán arrastrar un remolque o semirremolque, siempre que no superen el 50% de la masa en vacío del vehículo tractor y cumplan el resto de las condiciones establecidas en el apartado 4 del artículo 12 del citado Reglamento..",o:{a:"Las Motocicletas y quads ATV.",b:"Los Turismos, motocicletas y vehículos para personas con movilidad reducida.",c:"Las Motocicletas, vehículos de tres ruedas, ciclomotores, ciclos y bicicletas.",d:"Todas las respuestas anteriores son incorrecta."},correct:"c",why:{a:"Lista incompleta.",b:"Los turismos están sujetos a otras condiciones.",c:"Correcto: motos, tres ruedas, ciclomotores, ciclos y bicicletas (art.12.4 RGC).",d:"La c es correcta."}},
{n:225,q:"El Reglamento General de Circulación (RD 1428/2003) permite que las motocicletas, los vehículos de tres ruedas, los ciclomotores, los ciclos y bicicletas puedan arrastrar un remolque de determinadas características, siempre que...",o:{a:"La circulación sea durante el día y en condiciones que no disminuyan la visibilidad.",b:"El vehículo sea conducido por una persona mayor de edad.",c:"No circulen por vías interurbanas.",d:"Todas las respuestas anteriores son correctas."},correct:"a",why:{a:"✓ Respuesta oficial. Parcial.",b:"Parcial.",c:"Parcial.",d:"⚠ Mi respuesta inicial (incorrecta): Las tres condiciones deben cumplirse (art.12 RGC)."}},
{n:226,q:"El Reglamento General de Circulación (RD 1428/2003) permite que las motocicletas, los vehículos de tres ruedas, los ciclomotores, los ciclos y bicicletas puedan arrastrar un remolque de determinadas características, siempre que...",o:{a:"La velocidad a que se circule en estas condiciones quede reducida en un 10 por ciento respecto a las velocidades genéricas que para estos vehículos se establecen en el artículo 48 del citado Reglamento.",b:"No transporten personas en el vehículo remolcado.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{a:"Parcial.",b:"Parcial.",c:"Ambas condiciones se exigen.",d:"Las dos son ciertas."}},
{n:227,q:"Respecto a las dimensiones del vehículo y su carga, el art.13 del Reglamento General de Circulación (RD 1428/2003) establece que, en ningún caso, la longitud, anchura y altura de los vehículos y su carga excederá:",o:{a:"De la señalada en las normas reguladoras de los vehículos.",b:"De la señalada para la vía por la que circulen.",c:"Las respuestas a y b son incorrectas.",d:"Las respuestas a y b son correctas."},correct:"d",why:{a:"Parcial.",b:"Parcial.",c:"Ambas son ciertas.",d:"Correcto: rige el doble límite — el del vehículo y el de la vía."}},
{n:228,q:"En cuanto al transporte de cargas indivisibles en vehículos destinados exclusivamente al transporte de mercancías, el Reglamento General de Circulación (RD 1428/2003) dispone que podrán sobresalir...",o:{a:"Dos metros por la parte posterior y tres por la anterior, cuando la longitud del vehículo supere los 5 metros.",b:"En vehículos con longitud igual o inferior a 5 metros, dos tercios de la longitud del vehículo por cada extremo anterior y posterior",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"d",why:{a:"Las medidas indicadas no corresponden al art.13 RGC.",b:"La fracción «dos tercios» no es la legal.",c:"Ambas son incorrectas.",d:"Correcto: ninguna de las dos coincide con el RGC."}},
{n:229,q:"El transporte de cargas indivisibles que, inevitablemente, rebasen los límites señalados en el art.13.1 del Reglamento General de Circulación (RD 1428/2003), deberá realizarse mediante autorizaciones complementarias de circulación, que se regulan:",o:{a:"En el Reglamento General de Vehículos.",b:"Conforme a las normas y condiciones de circulación que se establecen en el anexo III del Reglamento General de Circulación.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{a:"No están en el RGV.",b:"Las autorizaciones complementarias se regulan en el Anexo I del RGC, no en el Anexo III.",c:"✓ Respuesta oficial. Ambas son incorrectas.",d:"⚠ Mi respuesta inicial (incorrecta): Correcto: el Anexo III es de pruebas deportivas; las complementarias están en el Anexo I."}},
{n:230,q:"La carga transportada en un vehículo, así como los accesorios que se utilicen para su acondicionamiento o protección, deben estar dispuestos y, si fuera necesario, sujetos de tal forma que:",o:{a:"No puedan arrastrar, caer total o parcialmente o desplazarse de manera peligrosa.",b:"No puedan comprometer la estabilidad del vehículo.",c:"No puedan producir ruido, polvo u otras molestias que puedan ser evitadas.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{a:"Parcial.",b:"Parcial.",c:"Parcial.",d:"Las tres condiciones deben cumplirse (art.14 RGC)."}},
{n:231,q:"La carga transportada en un vehículo, así como los accesorios que se utilicen para su acondicionamiento o protección, deben estar dispuestos y, si fuera necesario, sujetos de tal forma que no puedan:",o:{a:"Ocultar los dispositivos de alumbrado o de señalización luminosa.",b:"Ocultar las placas o distintivos obligatorios.",c:"Ocultar las advertencias manuales de sus conductores.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{a:"Parcial.",b:"Parcial.",c:"Parcial.",d:"Las tres prohibiciones están previstas."}},
{n:232,q:"Respecto a la disposición de la carga, regulada en el Art.14 del Reglamento General de Circulación (RD 1428/2003), indique la afirmación incorrecta:",o:{a:"El transporte de materias que produzcan polvo o puedan caer se efectuará siempre cubriéndolas total y eficazmente.",b:"El transporte de cargas molestas, nocivas, insalubres o peligrosas, se atendrá, además de lo previsto en dicho art.14, a las normas específicas que regulan la materia.",c:"El transporte de animales que puedan resultar lesionados durante el trayecto, se atendrá, además de lo previsto en dicho art.14, a lo previsto en el anexo III del Reglamento General de Circulación.",d:"El transporte de cargas que entrañen especialidades en su acondicionamiento o estiba, se atendrá, además de lo previsto en dicho art.14, a las normas específicas que regulan la materia."},correct:"c",why:{a:"Correcto.",b:"Correcto.",c:"El Anexo III regula pruebas deportivas, no el transporte de animales; éste se rige por su normativa específica.",d:"Correcto."}},
{n:233,q:"Respecto a las dimensiones de la carga, reguladas en el art.15 del Reglamento General de Circulación (RD 1428/2003), indique la afirmación incorrecta:",o:{a:"En el caso de que la dimensión menor de la carga indivisible sea superior al ancho del vehículo, podrá sobresalir hasta 0,55 metros por cada lateral, siempre que el ancho total no sea superior a 2,40 metros.",b:"La carga no sobresaldrá de la proyección en planta del vehículo, salvo en los casos y condiciones previstos en dicho art.15.",c:"En los vehículos de tracción animal, se entiende por proyección la del vehículo propiamente dicho prolongada hacia adelante, con su misma anchura, sin sobrepasar la cabeza del animal de tiro más próximo a aquél.",d:"En los vehículos no destinados exclusivamente al transporte de mercancías, la carga podrá sobresalir por la parte posterior hasta un 10 por ciento de su longitud, y si fuera indivisible, un 15 por ciento."},correct:"a",why:{a:"El máximo lateral es 0,40 m por cada lado y 2,55 m de ancho total, no 0,55 m y 2,40 m.",b:"Correcto.",c:"Correcto.",d:"Correcto."}},
{n:234,q:"Los vehículos destinados exclusivamente al transporte de mercancías, siempre que cumplan las condiciones establecidas para su estiba y acondicionamiento, cuando transporten vigas, postes, tubos u otras cargas de longitud indivisible, podrán sobresalir:",o:{a:"En vehículos de longitud superior a cinco metros, dos metros por la parte anterior y tres metros por la posterior.",b:"En vehículos de longitud igual o inferior a cinco metros, el tercio de la longitud del vehículo por cada extremo anterior y posterior.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{a:"En vehículos de mercancías la carga sobresale solo por la parte posterior (hasta 3 m), no por la anterior.",b:"Solo se permite el saliente posterior, no «por cada extremo anterior y posterior».",c:"✓ Respuesta oficial. Ambas son incorrectas.",d:"⚠ Mi respuesta inicial (incorrecta): Correcto: ambas afirmaciones son falsas."}},
{n:235,q:"El Reglamento General de Circulación dispone que las cargas indivisibles que sean superiores al ancho del vehículo, podrán sobresalir por cada lateral un máximo de...",o:{a:"0,25 metros.",b:"0,40 metros.",c:"0,55 metros.",d:"Ninguna de las respuestas anteriores es correcta."},correct:"b",why:{a:"Demasiado poco.",b:"Correcto: 0,40 m por lateral (art.15 RGC).",c:"Excede el límite.",d:"La b es correcta."}},
{n:236,q:"Los vehículos destinados exclusivamente al transporte de mercancías, siempre que cumplan las condiciones establecidas para su estiba y acondicionamiento, en el caso de que la dimensión menor de la carga indivisible que transporten sea superior al ancho del vehículo, podrá sobresalir:",o:{a:"Hasta 0,50 metros por cada lateral, siempre que el ancho total no sea superior a 2,45 metros.",b:"Hasta 0,40 metros por cada lateral, siempre que el ancho total no sea superior a 2,55 metros.",c:"Hasta 0,45 metros por cada lateral, siempre que el ancho total no sea superior a 2,50 metros.",d:"Hasta 0,60 metros por cada lateral, siempre que el ancho total no sea superior a 2,45 metros."},correct:"b",why:{a:"Medidas incorrectas.",b:"Correcto: 0,40 m por lateral y 2,55 m ancho total máximo.",c:"Medidas incorrectas.",d:"Medidas incorrectas."}},
{n:237,q:"Respecto a las dimensiones de la carga, reguladas en el art.15 del Reglamento General de Circulación (RD 1428/2003), indique la afirmación incorrecta:",o:{a:"En el caso de que la dimensión menor de la carga indivisible sea superior al ancho del vehículo, podrá sobresalir hasta 0,55 metros por cada lateral, siempre que el ancho total no sea superior a 2,40 metros.",b:"En los vehículos de anchura inferior a un metro la carga no deberá sobresalir lateralmente más de 0,50 metros a cada lado de su eje longitudinal. No podrá sobresalir por la extremidad anterior, ni más de 0,25 metros por la posterior.",c:"Cuando la carga sobresalga de la proyección en planta del vehículo, siempre dentro de los límites regulados en dicho art.15, se deberán adoptar todas las precauciones convenientes para evitar daños o peligros a los demás usuarios de la vía pública, y deberá ir resguardada en la extremidad saliente para aminorar los efectos de un roce o choque posibles.",d:"En todo caso, la carga que sobresalga por detrás de los vehículos deberá ser señalizada por medio de la señal V-20 a que se refiere el artículo 173 y cuyas características se establecen en el anexo XI del Reglamento General de Vehículos."},correct:"a",why:{a:"Las medidas correctas son 0,40 m por lateral y 2,55 m de ancho total, no 0,55 m y 2,40 m.",b:"Correcto.",c:"Correcto.",d:"Correcto."}},
{n:238,q:"Según establece el art.15 del Reglamento General de Circulación (RD 1428/2003), la señal para indicar la carga que sobresalga por detrás de los vehículos, deberá colocarse:",o:{a:"En el extremo posterior inferior izquierdo de la carga.",b:"En el extremo posterior de la carga de manera que quede constantemente perpendicular al eje del vehículo.",c:"En el extremo posterior superior izquierdo de la carga.",d:"Todas las respuestas anteriores son incorrectas."},correct:"b",why:{a:"No es esa la ubicación legal.",b:"Correcto: en el extremo posterior, perpendicular al eje del vehículo.",c:"No es esa la ubicación legal.",d:"La b es correcta."}},
{n:239,q:"Según establece el art.15 del Reglamento General de Circulación (RD 1428/2003), cuando la carga sobresalga longitudinalmente por toda la anchura de la parte posterior del vehículo, se colocarán transversalmente dos paneles de señalización...",o:{a:"Cada uno en un extremo de la carga.",b:"Cada uno en un extremo de la anchura del material que sobresalga.",c:"Cada uno en un extremo del lugar citado en la respuesta a) o b).",d:"Todas las respuestas anteriores son incorrectas."},correct:"c",why:{a:"Parcial.",b:"Parcial.",c:"Correcto: en un extremo del lugar previsto, según el caso.",d:"La c es correcta."}},
{n:240,q:"Según establece el art.15 del Reglamento General de Circulación (RD 1428/2003), los paneles que han de señalizar la carga que sobresalga longitudinalmente por toda la anchura del vehículo:",o:{a:"Deberán colocarse de tal manera que formen una geometría de \"V\" invertida.",b:"Deberán colocarse de tal manera que formen una geometría de \"V\".",c:"Deberán colocarse de tal manera que formen una geometría de \"W\" invertida.",d:"Deberán colocarse de tal manera que formen una geometría de \"W\"."},correct:"a",why:{a:"Correcto: forman una «V» invertida.",b:"No es «V» normal.",c:"No es «W».",d:"No es «W»."}},
{n:241,q:"El Reglamento General de Circulación (RD 1428/2003) dispone que cuando el vehículo circule entre la puesta y la salida del sol o bajo condiciones meteorológicas o ambientales que disminuyan sensiblemente la visibilidad, cuando la carga sobresalga deberá ir señalizada con la señal V-20 y, además, mediante:",o:{a:"Una luz roja si sobresale por la parte posterior y una luz blanca si sobresale por delante.",b:"La señal V-30.",c:"Una luz blanca en la parte posterior y una luz roja en la parte delantera.",d:"Ninguna de las respuestas anteriores es correcta."},correct:"a",why:{a:"Correcto: luz roja atrás, blanca delante.",b:"No es la V-30.",c:"Es al revés.",d:"La a es correcta."}},
{n:242,q:"Entre la puesta y la salida del sol, las cargas que sobresalgan lateralmente del gálibo del vehículo, de tal manera que su extremidad lateral se encuentre a más de 0,40 metros del borde exterior de la luz delantera o trasera de posición del vehículo, deberán estar señalizadas, en cada una de sus extremidades laterales:",o:{a:"Hacia adelante, por medio de una luz blanca y un dispositivo reflectante de color blanco.",b:"Hacia atrás, por medio de una luz roja y de un dispositivo reflectante de color rojo.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{a:"Parcial.",b:"Parcial.",c:"Ambas señalizaciones son exigidas.",d:"Las dos son ciertas."}},
{n:243,q:"Cuando existan condiciones meteorológicas o ambientales que disminuyan sensiblemente la visibilidad, las cargas que sobresalgan lateralmente del gálibo del vehículo, de tal manera que su extremidad lateral se encuentre a más de 0,40 metros del borde exterior de la luz delantera o trasera de posición del vehículo, deberán estar señalizadas, en cada una de sus extremidades laterales:",o:{a:"Hacia adelante, por medio de una luz blanca y un dispositivo reflectante de color blanco.",b:"Hacia atrás, por medio de una luz roja y de un dispositivo reflectante de color rojo.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{a:"Parcial.",b:"Parcial.",c:"Ambas son ciertas.",d:"Las dos son ciertas."}},
{n:244,q:"Respecto a las operaciones de carga y descarga, el art.16 del Reglamento General de Circulación (RD 1428/2003), dispone que:",o:{a:"Las operaciones de carga o descarga deberán llevarse a cabo fuera de la vía.",b:"Excepcionalmente, cuando sea inexcusable efectuar la carga y descarga en la vía, deberán realizarse sin ocasionar peligros ni perturbaciones graves al tránsito de otros usuarios y teniendo en cuenta las normas establecidas en dicho artículo:",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{a:"Parcial.",b:"Parcial.",c:"Ambas son correctas (art.16 RGC).",d:"Las dos son ciertas."}},
{n:245,q:"Cuando excepcionalmente sea inexcusable efectuar operaciones de carga y descarga en la vía, teniendo en cuenta las normas establecidas en el art.16 del Reglamento General de Circulación (RD 1428/2003):",o:{a:"Se respetarán las disposiciones sobre paradas y estacionamientos, y, además, en poblado, las que dicten las autoridades municipales sobre horas y lugares adecuados.",b:"Se efectuarán, en lo posible, por el lado del vehículo más próximo al borde de la calzada.",c:"Se llevarán a cabo con medios suficientes para conseguir la máxima celeridad, y procurando evitar ruidos y molestias innecesarias.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{a:"Parcial.",b:"Parcial.",c:"Parcial.",d:"Las tres normas se aplican a estas operaciones."}},
{n:246,q:"Respecto a la excepcionalidad de realizar operaciones de carga y descarga en la vía, el art.16 del Reglamento General de Circulación (RD 1428/2003), dispone que:",o:{a:"Las operaciones que se realicen en la vía no podrán exceder de 15 minutos.",b:"Queda prohibido depositar la mercancía en la calzada, arcén y zonas peatonales.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"b",why:{a:"No existe ese límite genérico de 15 minutos en el art.16 RGC.",b:"Correcto: prohibido depositar la mercancía en calzada, arcén y zonas peatonales.",c:"La a no es cierta.",d:"La b sí lo es."}},
{n:247,q:"Según lo previsto en el art.16 del Reglamento General de Circulación (RD 1428/2003), las operaciones de carga y descarga de mercancías molestas, nocivas, insalubres o peligrosas, así como las que entrañen especialidades en su manejo o estiba, se regirán, además de lo previsto en este artículo:",o:{a:"Por lo previsto en la codificación establecida en el Anexo I para la mercancía de que se trate.",b:"Por las disposiciones específicas que regulan la materia.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"b",why:{a:"El Anexo I es de vehículos especiales, no de mercancías peligrosas.",b:"Correcto: se rigen por las disposiciones específicas (ADR, etc.).",c:"La a no es cierta.",d:"La b sí lo es."}},
{n:248,q:"El Capítulo III del Título I del Reglamento General de Circulación (RD 1428/2003) se denomina:",o:{a:"Normas Generales.",b:"De la carga de vehículos y del transporte de personas y mercancías o cosas.",c:"Normas generales de los conductores.",d:"Normas sobre estupefacientes, psicotrópicos, estimulantes u otras sustancias análoga"},correct:"c",why:{a:"Es Cap.I.",b:"Es Cap.II.",c:"Correcto: Cap.III — Normas generales de los conductores.",d:"Es Cap.V."}},
{n:249,q:"Respecto al Control del vehículo o de animales, el art.17 del Reglamento General de Circulación (RD 1428/2003) dispone que los conductores:",o:{a:"Deberán estar en todo momento en condiciones de controlar sus vehículos o animales.",b:"Al aproximarse a otros usuarios de la vía, deberán adoptar las precauciones necesarias para su seguridad, especialmente cuando se trate de niños, ancianos, invidentes u otras personas manifiestamente impedidas.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{a:"Parcial.",b:"Parcial.",c:"Ambas son obligaciones del conductor (art.17 RGC).",d:"Las dos son ciertas."}},
{n:250,q:"El art.17 del Reglamento General de Circulación (RD 1428/2003), prohíbe a los conductores de caballerías, ganados y vehículos de carga de tracción animal:",o:{a:"Llevarlos corriendo por la vía en las inmediaciones de otros de la misma especie o de las personas que van a pie.",b:"Abandonar su conducción, dejándoles marchar libremente por el camino o detenerse en él.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{a:"Parcial.",b:"Parcial.",c:"Ambas conductas están prohibidas.",d:"Las dos son ciertas."}},
{n:251,q:"Para garantizar su propia seguridad, la del resto de los ocupantes del vehículo y la de los demás usuarios de la vía, el conductor de un vehículo está obligado a mantener:",o:{a:"Su propia libertad de movimientos.",b:"El campo necesario de visión.",c:"La atención permanente a la conducción.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{a:"Parcial.",b:"Parcial.",c:"Parcial.",d:"Las tres exigencias son del art.18 RGC."}},
{n:252,q:"A los efectos de garantizar su propia seguridad y la del resto de ocupantes del vehículo y usuarios de la vía, el conductor de un vehículo deberá cuidar especialmente de mantener:",o:{a:"La posición adecuada y que la mantengan el resto de los pasajeros.",b:"La adecuada colocación de los objetos o animales transportados para que no haya interferencia entre el conductor y cualquiera de ellos.",c:"Las respuestas a y b son incorrectas.",d:"Las respuestas a y b son correctas."},correct:"d",why:{a:"Parcial.",b:"Parcial.",c:"Ambas son ciertas.",d:"Correcto: ambas exigencias se derivan del art.18 RGC."}},
{n:253,q:"El Reglamento General de Circulación (RD 1428/2003) considera incompatible con la obligatoria atención permanente a la conducción, el uso por el conductor con el vehículo en movimiento de...",o:{a:"Dispositivos GPS.",b:"Monitores que estén a la vista del conductor y cuya utilización sea necesaria para la visión de acceso o bajada de peatones o de maniobras traseras.",c:"Pantallas con acceso a internet, monitores de televisión y reproductores de vídeo o DVD.",d:"Todos los dispositivos indicados en las respuestas anteriores."},correct:"c",why:{a:"Los GPS son compatibles.",b:"Los monitores para maniobras son compatibles.",c:"Correcto: pantallas de internet, TV y DVD son incompatibles con la atención permanente.",d:"La a y b sí son compatibles."}},
{n:254,q:"Respecto a determinadas obligaciones del conductor, establecidas en el art.18 del Reglamento General de Circulación (RD 1428/2003), indique cual de las siguientes es incorrecta:",o:{a:"Queda prohibido conducir y utilizar cascos o auriculares conectados a aparatos receptores o reproductores de sonido, excepto durante la correspondiente enseñanza y la realización de las pruebas de aptitud en circuito abierto para la obtención del permiso de conducción de motocicletas de dos ruedas cuando así lo exija el Reglamento General de Conductores.",b:"Se prohíbe la utilización durante la conducción de dispositivos de telefonía móvil y cualquier otro medio o sistema de comunicación, excepto cuando el desarrollo de la comunicación tenga lugar sin emplear las manos ni usar cascos, auriculares o instrumentos similares.",c:"Quedan exentos de la prohibición del uso de telefonía móvil los agentes de la autoridad y los conductores de vehículos de servicio público, cuando realicen servicios de emergencias en ejercicio de las funciones que tengan encomendadas.",d:"Se prohíbe que en los vehículos se instalen mecanismos o sistemas, se lleven instrumentos o se acondicionen de forma encaminada a eludir la vigilancia de los agentes de tráfico, o que se emitan o hagan señales con dicha finalidad, así como la utilización de mecanismos de detección de radar."},correct:"c",why:{a:"Correcto.",b:"Correcto.",c:"La excepción legal se refiere solo a los agentes de la autoridad en ejercicio de sus funciones; no se extiende, con carácter general, a los conductores de servicios públicos.",d:"Correcto."}},
{n:255,q:"Respecto a la visibilidad en el vehículo, regulada en el art.19 del Reglamento General de Circulación (RD 1428/2003), indique la afirmación incorrecta:",o:{a:"La superficie acristalada del vehículo deberá permitir, en todo caso, la visibilidad diáfana del conductor sobre toda la vía por la que circule, sin interferencias de láminas o adhesivos.",b:"Queda prohibida, en determinados casos, la colocación de vidrios tintados o coloreados no homologados.",c:"Únicamente se permitirá circular con láminas adhesivas o cortinillas contra el sol en las ventanillas posteriores cuando el vehículo lleve dos espejos retrovisores exteriores que cumplan las especificaciones técnicas necesarias.",d:"La utilización de láminas adhesivas en los vehículos se permitirá en las condiciones establecidas en la reglamentación de vehículos."},correct:"b",why:{a:"Correcto.",b:"La prohibición es «en todo caso», no «en determinados casos».",c:"Correcto.",d:"Correcto."}},
{n:256,q:"Respecto a la visibilidad en el vehículo, regulada en el art.19 del Reglamento General de Circulación, indique la afirmación incorrecta:",o:{a:"Únicamente se permitirá circular con láminas adhesivas en las ventanillas posteriores cuando el vehículo lleve dos espejos retrovisores exteriores que cumplan la norma aplicable y garantice la visibilidad.",b:"La colocación de los distintivos previstos en la legislación de transportes o en otras disposiciones deberá realizarse de forma que no impidan la correcta visión del conductor.",c:"Queda prohibida, en todo caso, la colocación de vidrios tintados o coloreados no homologados.",d:"Únicamente se permitirá circular con cortinillas contra el sol en las ventanillas posteriores cuando el vehículo lleve dos espejos retrovisores exteriores que cumplan las especificaciones técnicas necesarias."},correct:"a",why:{a:"La fórmula legal correcta es «que cumplan la norma aplicable» o equivalente; la fórmula doble «y garantice la visibilidad» no figura en la redacción legal de la opción correcta (compárese con la opción d para «cortinillas»).",b:"Correcto.",c:"Correcto.",d:"Correcto."}}
];
